'use strict';
(function(){
const D=globalThis.RA.D;
const q=(prompt,answer,d1,d2,explain,sense=1,type='meaning')=>({prompt,answer,d1,d2,explain,sense,type});
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({errorType,wrong,right,reason});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:'Etymonline: https://www.etymonline.com/word/'+w.toLowerCase().replaceAll(' ','-')});
const P=(w,origin,c,m,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(c)?c:[c],mistakes:[m],quiz:qs.map((x,i)=>({id:w+'.q'+(i+1),senseId:w+'.s'+x.sense,type:'辨义与用法',prompt:x.prompt,options:[x.answer,x.d1,x.d2],answer:x.answer,explain:x.explain,errorType:x.type}))});
P('reclamation','Reclamation comes through French from Latin reclamatio, “a calling back”; it now commonly means making land usable again or recovering useful material from waste.',[C('reclamation.s1','开垦；围垦','The reclamation of the marsh created new farmland, but the planners preserved a strip of wetland for birds.','沼泽开垦后形成了新农田，但规划者为鸟类保留了一片湿地。','The reclamation of the marsh / created new farmland / while preserving a wetland strip.','reclamation.s1 指把荒地或湿地改造成可耕作、建设的土地。','项目把部分沼泽改成农田，同时保留栖息地。'),C('reclamation.s2','回收；再利用','The reclamation of copper from discarded cables reduced the need to mine new ore.','从废弃电缆中回收铜，减少了开采新矿石的需求。','The reclamation of copper / from discarded cables / reduced new mining.','reclamation.s2 指从废物中取回有用材料。','回收铜材可减少新矿开采。')],M('The factory praised its reclamation program, which buried usable copper in a landfill instead of recovering it.','The factory praised its reclamation program, which recovered usable copper from discarded cables.','回收项目应取回并再利用材料，而不是把材料埋进填埋场。','meaning'),[q('What did marsh reclamation create?','new farmland while preserving a wetland strip','a copper cable factory','a dry road through the city','沼泽开垦形成了农田并保留湿地。',1,'context'),q('What did the factory reclaim from old cables?','copper','wetland birds','farm soil','工厂从旧电缆中回收铜。',2,'context'),q('Which is material reclamation?','recovering glass from discarded bottles','burying reusable glass in a landfill','building a recliner from new wood','从废瓶中回收玻璃属于材料回收。',2,'meaning'),q('What is a common purpose of land reclamation?','make waste land usable for farming or building','make useful material impossible to reuse','call a meeting back to order','土地开垦可使荒地适合农业或建设。',1,'meaning')]);
P('recline','Recline comes from Latin reclinare, “to bend back”; it means lean backward or lie in a relaxed position.',C('recline.s1','斜倚；躺卧','Passengers may recline their seats after takeoff, but they must return them upright before landing.','飞机起飞后乘客可以调低座椅，但着陆前必须将座椅调直。','Passengers may recline their seats / after takeoff / but must raise them before landing.','recline 指向后倾斜或舒适地躺靠。','座椅起飞后可向后斜倚。'),M('The passenger reclined upright by forcing the seat farther forward and sitting at attention.','The passenger reclined by leaning the seat back after takeoff.','recline 表示向后倾斜或躺靠，不是向前挺直坐好。','meaning'),[q('When may passengers recline their seats?','after takeoff','during the final landing approach','while the aircraft is parked with doors open','乘客起飞后可以调低座椅。'),q('What must passengers do before landing?','return the seats upright','recline them as far as possible','remove the seats from the cabin','着陆前要把座椅恢复直立。',1,'context'),q('Which posture is reclined?','leaning back in a chair','standing straight beside a wall','bending forward to lift a box','斜倚是向后靠在椅子上。',1,'meaning'),q('Which Latin verb is behind recline?','reclinare, “to bend back”','recognoscere, “to know again”','recludere, “to shut away”','recline 源自拉丁语 reclinare，意为“向后弯”。',1,'word-formation')]);
P('recluse','Recluse came through Old French reclus from Latin recludere, “to shut away”; it names someone who deliberately lives apart from other people.',C('recluse.s1','遁世者；隐居者','The recluse lived in a cabin beyond the village and rarely attended public events.','这位隐居者住在村外的小屋里，很少参加公共活动。','The recluse lived beyond the village / and rarely attended / public events.','recluse 指主动远离社交、独自生活的人。','他长期住在村外，很少与人来往。'),M('The recluse spent every evening hosting large parties for the entire village and seeking new company.','The recluse lived alone beyond the village and avoided most social gatherings.','经常主持大型聚会并寻求交往，与遁世者远离社交的含义不符。','meaning'),[q('Where did the recluse live?','in a cabin beyond the village','in the center of a busy market','in a crowded public hall','隐居者住在村外小屋。'),q('What did the recluse rarely attend?','public events','quiet mornings alone','a cabin in the woods','隐居者很少参加公共活动。',1,'context'),q('Who is a recluse?','someone who lives apart from other people','someone who recommends books to others','someone who repairs a railway','recluse 指远离社交、独自生活的人。',1,'meaning'),q('What image underlies the Latin source recludere?','shutting someone away','calling someone back to speak','leaning backward in a chair','recluse 的拉丁词源包含“关起来、隔开”的意象。',1,'word-formation')]);
P('reclusive','Reclusive is formed from recluse with -ive; it describes a person or way of life that avoids company and social activity.',C('reclusive.s1','隐居的；不合群的','After retiring, the scientist became reclusive and stopped giving interviews, though she continued corresponding with former students.','退休后，这位科学家变得深居简出，不再接受采访，但仍与以前的学生通信。','The scientist became reclusive / and stopped giving interviews / though she kept writing to students.','reclusive 描述倾向于独处、避免社交的生活方式。','她不再接受采访，但仍与少数人保持联系。'),M('The biography called the actor reclusive because he attended every public party and gave interviews each week.','The biography called the actor reclusive because he avoided public events and rarely spoke to reporters.','频繁参加聚会并接受采访不符合 reclusive 的社交回避含义。','meaning'),[q('What changed after the scientist retired?','she stopped giving interviews','she began hosting weekly public parties','she moved into a crowded station','她退休后不再接受采访。'),q('With whom did she continue corresponding?','former students','the entire village at public rallies','strangers at every party','她仍与以前的学生通信。',1,'context'),q('What does reclusive describe?','a tendency to avoid social activity','a willingness to host large gatherings','a plan to rebuild a damaged bridge','reclusive 指倾向于避免社交。',1,'meaning'),q('Which suffix helps form reclusive from recluse?','-ive','-tion','-er','recluse 加 -ive 构成形容词 reclusive。',1,'word-formation')]);
P('recognition','Recognition comes from recognize plus -tion, ultimately from Latin recognoscere, “to know again”; it can mean identifying someone or acknowledging something.',C('recognition.s1','认出；承认','The witness identified the driver by voice recognition after hearing a short recording.','听了一段录音后，证人通过声音辨认出了司机。','The witness identified the driver / by voice recognition / after hearing a recording.','recognition.s1 指认出某人或某物，也可指承认某事物。','证人凭声音认出了司机。'),M('The witness claimed voice recognition was impossible because she correctly identified the driver from the recording.','The witness used voice recognition to identify the driver from the recording.','成功辨认正说明声音识别发生了，并非不可能。','meaning'),[q('How did the witness identify the driver?','by voice recognition','by reading a rainfall chart','by rebuilding a damaged recorder','证人听录音后通过声音辨认了司机。'),q('What does recognition mean in voice recognition?','identifying a person or thing','rebuilding it from broken pieces','recommending it for an award','voice recognition 指通过声音辨认身份。',1,'meaning'),q('Which noun names the act of recognizing?','recognition','recline','recomposition','recognition 是 recognize 的名词形式。',1,'word-formation'),q('What did the witness hear before identifying the driver?','a short recording','a public rally','a quiet recluse’s interview','证人听了一段录音后作出辨认。',1,'context')]);
P('recognizable','Recognizable is formed from recognize and -able; it means easy enough to identify or know again.',C('recognizable.s1','认得出的；可识别的','Even through the thick fog, the lighthouse remained recognizable by its three red bands.','即使隔着浓雾，人们仍能通过灯塔上的三道红色带纹认出它。','The lighthouse remained recognizable / by its three red bands / through the fog.','recognizable 表示特征足够明显，能使人认出或识别。','红色带纹使灯塔在浓雾中仍可辨认。'),M('The lighthouse was recognizable because every identifying feature had been removed and nobody could tell it apart from others.','The lighthouse was recognizable because its three red bands remained visible through the fog.','辨认需要仍有可识别特征；特征全被去掉就无法认出。','meaning'),[q('How could visitors recognize the lighthouse in fog?','by its three red bands','by its hidden radio code','by a newly built railway','人们通过三道红色带纹辨认灯塔。'),q('What does recognizable mean?','easy enough to identify','impossible to see or distinguish','likely to be recommended','recognizable 表示容易辨认。',1,'meaning'),q('Which detail makes a face recognizable?','a distinctive scar that remains visible','removing every feature from the photograph','covering the face completely','仍然可见的独特疤痕有助于辨认面孔。',1,'context'),q('What does -able contribute to recognizable?','the possibility or ease of being recognized','the past tense of recognize','the noun naming a person who recognizes','-able 表示可以或容易被辨认。',1,'word-formation')]);
P('recognize','Recognize comes from Latin recognoscere, “to know again”; it means identify, accept as true, or acknowledge officially.',[C('recognize.s1','认出；识别','I recognized the old station by its green clock, although the shops around it had changed.','尽管车站周围的商店都变了，我还是凭那只绿色钟认出了旧车站。','I recognized the station / by its green clock / though nearby shops had changed.','recognize.s1 指凭熟悉的特征认出人或物。','绿色钟帮助说话者认出旧车站。'),C('recognize.s2','承认；意识到','The committee recognized that its original timetable could not accommodate the new safety inspections.','委员会意识到原定时刻表无法容纳新增的安全检查。','The committee recognized / that its original timetable / could not fit the inspections.','recognize.s2 指承认某事真实存在或意识到事实。','委员会承认原时刻表安排不下检查。'),C('recognize.s3','正式承认；赞誉','The university recognized the engineer’s contribution by awarding her an honorary degree.','大学授予这位工程师荣誉学位，以正式表彰她的贡献。','The university recognized the engineer / by awarding / an honorary degree.','recognize.s3 可指正式承认地位或公开表彰成就。','授予荣誉学位是正式表彰。')],M('The committee recognized the safety problem by insisting that no problem existed and refusing to change its timetable.','The committee recognized the safety problem and revised its timetable to allow inspections.','否认问题存在不等于承认或意识到问题。','meaning'),[q('What feature helped identify the old station?','its green clock','its new timetable','a red band on the lighthouse','说话者凭绿色钟认出了旧车站。',1,'context'),q('What did the committee recognize about its timetable?','it could not fit the new safety inspections','it already included every required inspection','it had been awarded an honorary degree','委员会承认原时刻表无法安排新增检查。',2,'context'),q('How did the university recognize the engineer?','it awarded her an honorary degree','it hid her name from the public','it changed the station clock','大学授予工程师荣誉学位以表彰她。',3,'context'),q('Which meaning is used in “I recognized the station”?','identified it from familiar features','officially honored it','accepted an inconvenient fact','这里 recognize 表示凭特征认出。',1,'meaning')]);
P('recognized','Recognized is the past form and participle of recognize; as an adjective it means accepted as correct, established or important.',C('recognized.s1','公认的；被认可的','The recognized safety standard requires a second inspection before the bridge can reopen.','公认的安全标准要求桥梁重新开放前再检查一次。','The recognized standard requires / a second inspection / before reopening.','recognized.s1 表示被普遍接受或正式认可的。','桥梁重开前须符合公认标准。'),M('The engineer called the recognized standard widely accepted, although no agency or professional group had ever accepted it.','The engineer called the recognized standard widely accepted because professional groups had adopted it.','recognized 表示被接受或认可，不能同时声称从未有人采纳。','meaning'),[q('What must happen before the bridge reopens?','a second inspection','a public rally','a radio interview','公认标准要求重新检查桥梁。'),q('What does recognized mean before standard?','accepted as correct or established','easy to recline in','likely to collapse','recognized standard 指被接受或公认的标准。',1,'meaning'),q('Which is a recognized qualification?','a certificate accepted by the professional board','a private note nobody has reviewed','an unidentified label with no criteria','由专业委员会认可的证书是公认资质。',1,'context'),q('Which verb form is recognized related to?','recognize','recompose','recline','recognized 是 recognize 的过去式和过去分词。',1,'grammar')]);
P('recoil','Recoil came through French reculer, “to move back”; it can mean a gun’s backward motion when fired or a sudden movement away in fear or disgust.',[C('recoil.s1','后坐力','The shooter braced her shoulder before firing because the rifle’s recoil was stronger than that of the training model.','开枪前，射手抵住肩膀，因为这支步枪的后坐力比训练枪更强。','The shooter braced her shoulder / before firing / because of the recoil.','recoil.s1 指枪械发射时向后冲的运动或作用力。','射手预先抵肩以承受后坐力。'),C('recoil.s2','畏缩；退缩','He recoiled from the spoiled milk as soon as its sour smell reached him.','一闻到变质牛奶的酸味，他就厌恶地退开了。','He recoiled from the milk / when its sour smell / reached him.','recoil.s2 指因恐惧、厌恶等突然向后退缩。','难闻气味使他退避。')],M('The rifle’s recoil pushed the shooter forward into the target instead of moving backward after the shot.','The rifle’s recoil pushed backward against the shooter’s shoulder after the shot.','recoil 指枪械发射后的后向运动，不是向前冲。','meaning'),[q('Why did the shooter brace her shoulder?','the rifle had strong recoil','the rifle was a recognized standard','a rainstorm began at the range','射手为承受步枪的后坐力而抵肩。',1,'context'),q('What made the man recoil from the milk?','its sour smell','its recognizable label','the sound of a public rally','酸味让他厌恶地退开。',2,'context'),q('Which movement is recoil in the gun sense?','the backward motion after firing','the movement of a trigger forward before firing','the slow rotation of a wheel','枪械 recoil 指射击后的向后运动。',1,'meaning'),q('Which feeling can cause someone to recoil?','disgust','recognition of a familiar station','relief after recovery','厌恶可能使人突然退缩。',2,'meaning')]);
P('recollect','Recollect combines re- and collect, from Latin colligere “gather”; it means gather a memory again or remember something.',C('recollect.s1','回忆起；想起','She recollected the route to the clinic by picturing the red bridge and the bakery on the corner.','她通过回想红桥和街角面包店，记起了去诊所的路线。','She recollected the route / by picturing the red bridge / and the corner bakery.','recollect 指从记忆中重新想起信息或经历。','两个地标帮助她回忆起路线。'),M('She recollected the route by forgetting every landmark and making up a road she had never seen.','She recollected the route by recalling the bridge and bakery she had passed.','recollect 是回想真实记忆，不是忘掉线索后编造路线。','meaning'),[q('Which landmarks helped her recollect the route?','the red bridge and corner bakery','the railway railhead and the station clock','the forest and the coast','她凭红桥和街角面包店想起路线。',1,'context'),q('What does recollect mean?','remember something from the past','recommend something to a friend','build something again from pieces','recollect 表示回忆起过去的事情。',1,'meaning'),q('Which sentence uses recollect correctly?','I recollect meeting the engineer at the clinic last year.','I recollect the bridge by forgetting where it is.','I recollect the chair by leaning back in it.','recollect meeting 表示记得曾经见过工程师。',1,'grammar'),q('What does the element collect suggest in recollect?','gathering something again, here a memory','closing something away from people','moving backward after a shot','recollect 中 collect 呼应“重新聚集”记忆的含义。',1,'word-formation')]);
P('recollection','Recollection is formed from recollect and -ion; it means a memory of something or the ability to remember it.',C('recollection.s1','回忆；记忆','Her earliest recollection was sitting beside her grandfather as he repaired a small radio.','她最早的记忆是坐在祖父身边，看他修理一台小收音机。','Her earliest recollection / was sitting beside her grandfather / as he repaired a radio.','recollection.s1 指记起的经历或回忆能力。','她记得小时候看祖父修收音机。'),M('His recollection of the event was perfectly clear because he could not remember any part of it.','His recollection of the event was clear because he remembered the main details.','recollection 是记忆或回忆，完全不记得就谈不上清晰回忆。','meaning'),[q('What was her earliest recollection?','watching her grandfather repair a radio','attending a rally about railway safety','rebuilding a damaged bridge','她最早的记忆是看祖父修收音机。'),q('What does recollection mean?','a memory or the ability to remember','a sudden backward movement','a public meeting','recollection 指记忆或回忆能力。',1,'meaning'),q('Which phrase is natural?','a vivid recollection of childhood','a reclined recollection of a railway','a recognizable recollection to repair','a vivid recollection of childhood 是自然搭配。',1,'collocation'),q('Which verb is recollection based on?','recollect','recoil','reconstitute','recollection 由 recollect 加 -ion 构成。',1,'word-formation')]);
P('recommend','Recommend came through French from Latin commendare, “entrust or commend”; it can endorse a suitable choice, advise an action, or make something attractive.',[C('recommend.s1','推荐；举荐','The mechanic recommended a local garage whose staff had repaired several cars for her family.','修理工推荐了一家本地车库，那里的员工曾为她家修过好几辆车。','The mechanic recommended a local garage / whose staff had repaired / her family’s cars.','recommend.s1 指认为某人或某物适合某种目的并加以推荐。','她根据实际经验推荐了车库。'),C('recommend.s2','建议；劝告','The doctor recommended that he rest for two days before returning to training.','医生建议他休息两天后再恢复训练。','The doctor recommended that he rest / for two days / before training again.','recommend.s2 指建议某人采取某种行动。','医生建议病人暂缓训练。'),C('recommend.s3','使有吸引力；使受欢迎','The quiet location and reliable service recommend the inn to travelers seeking a restful stop.','安静的位置和可靠的服务使这家旅店很适合想要安静歇脚的旅客。','The location and service recommend the inn / to travelers / seeking a restful stop.','recommend.s3 可表示某种特点使事物值得选择。','旅店的地点与服务让它适合需要休息的旅客。')],M('The doctor recommended him to train immediately even though the recommendation was to rest for two days.','The doctor recommended that he rest for two days before training again.','医生建议休息，不是立即训练；两句建议相互矛盾。','grammar'),[q('Why did the mechanic recommend the garage?','its staff had repaired cars for her family','it had a reclinable passenger seat','it offered a raffle for radio parts','修理工根据车库员工的实际维修经验作推荐。',1,'context'),q('What did the doctor recommend?','resting for two days','training immediately','reconstructing the clinic','医生建议休息两天。',2,'context'),q('What makes the inn recommend itself to restful travelers?','its quiet location and reliable service','its loud late-night rally','its unstable bridge','安静地点和可靠服务使旅店值得选择。',3,'context'),q('Which construction is correct after recommend as advice?','The doctor recommended that he rest.','The doctor recommended that he rests.','The doctor recommended him resting that he rest.','recommend 后接 that 从句时常用动词原形 rest。',2,'grammar')]);
P('recommendation','Recommendation comes from recommend plus -ation; it can be advice, an endorsement, or a letter praising someone for a position or course.',[C('recommendation.s1','推荐；建议','The guide’s recommendation was to take the lower trail because the ridge remained icy.','向导建议走较低的步道，因为山脊上仍有冰。','The guide’s recommendation / was to take the lower trail / because the ridge was icy.','recommendation.s1 可指对选择或行动的建议。','向导根据路况建议选择低处路线。'),C('recommendation.s2','推荐信','She attached a recommendation from her former supervisor to the application for a research fellowship.','她在研究奖学金申请中附上了前主管写的推荐信。','She attached a recommendation / from her former supervisor / to the fellowship application.','recommendation.s2 指为求职或升学等目的评价并推荐某人的信件。','申请人附上了前主管的推荐信。'),C('recommendation.s3','正式建议；提议','The safety panel issued a recommendation that every bridge receive a full inspection each year.','安全委员会正式建议每座桥每年都接受一次全面检查。','The panel issued a recommendation / that every bridge receive / a yearly inspection.','recommendation.s3 可指正式提出的行动建议。','委员会正式提出年度检查建议。')],M('The applicant attached a recommendation letter written by no one who knew her and containing no praise or evaluation.','The applicant attached a recommendation letter from her former supervisor describing her research work.','推荐信应由了解申请人的人撰写，并对其能力作评价。','meaning'),[q('Which trail did the guide recommend?','the lower trail','the icy ridge','the unmarked railway','向导建议走较低的步道。',1,'context'),q('What did the applicant attach to the fellowship application?','a recommendation from her former supervisor','a bridge inspection record','a train ticket','她附上了前主管的推荐信。',2,'context'),q('What did the safety panel formally propose?','a yearly inspection for every bridge','closing every trail for a year','replacing all recommendations with raffles','安全委员会建议每年检查每座桥。',3,'context'),q('Which recommendation is a letter of endorsement?','a former supervisor’s letter supporting an applicant','a guide’s advice about which trail to take','a panel’s proposal for bridge inspections','主管为申请人撰写的支持信是推荐信。',2,'meaning')]);
P('recompose','Recompose combines re- and compose, “put together”; it means form something again or regain emotional self-control.',[C('recompose.s1','重新组成；使平静','After the unexpected question, the violinist took a breath to recompose herself before answering the interviewer.','面对突如其来的问题，小提琴家深吸一口气，让自己平静下来后再回答采访者。','The violinist paused to recompose herself / before answering / the interviewer.','recompose.s1 指重新组成某物，也可指调整情绪、恢复镇定。','她停顿片刻使自己恢复镇定。')],M('The violinist recomposed herself by becoming more upset and losing control before answering.','The violinist recomposed herself by taking a breath and regaining her calm.','recompose oneself 表示恢复镇静，而不是变得更激动。','meaning'),[q('What did the violinist do before answering?','paused and took a breath','left the interview without speaking','recomposed the interviewer’s written notes','她先深呼吸让自己平静。'),q('What does recompose oneself mean?','regain emotional self-control','rebuild a bridge from stones','recommend someone for a job','recompose oneself 表示恢复镇静。',1,'meaning'),q('Which sentence uses recompose in the emotional sense?','He paused to recompose himself after the startling news.','She recomposed the broken table from its boards.','They recommended the composer for an award.','第一句中的 recompose oneself 表示使自己平静下来。',1,'context'),q('What does re- suggest in recompose?','again','without','before','re- 在 recompose 中表示“再次、重新”。',1,'word-formation')]);
P('reconcile','Reconcile comes from Latin reconciliare, “to bring together again”; it can restore friendly relations, make facts consistent, or accept a difficult situation.',[C('reconcile.s1','使和解；调解','A mediator helped the two neighbors reconcile after they agreed to replace the fence damaged during construction.','两位邻居同意更换施工中损坏的篱笆后，调解员帮助他们和解。','A mediator helped the neighbors reconcile / after they agreed / to replace the damaged fence.','reconcile.s1 指使争吵或疏远的人恢复友好关系。','邻居解决纠纷后恢复了关系。'),C('reconcile.s2','调和；使一致','The accountant reconciled the travel receipts with the company’s expense ledger before submitting the report.','提交报告前，会计核对了差旅收据与公司的费用账簿，使两者一致。','The accountant reconciled the receipts / with the expense ledger / before submitting the report.','reconcile.s2 指找出办法使看似矛盾的记录或观点相符。','会计核对收据与账簿。'),C('reconcile.s3','将就；安于','After several months, he reconciled himself to the fact that the old theater would not reopen.','几个月后，他接受了老剧院不会重新开放这一事实。','He reconciled himself to the fact / that the old theater / would not reopen.','reconcile.s3 常见于 reconcile oneself to，表示接受不理想的处境。','他逐渐接受剧院不会重开的现实。')],M('The accountant reconciled the receipts with the ledger by ignoring every difference and submitting totals that still disagreed.','The accountant reconciled the receipts with the ledger by checking and correcting the discrepancies.','reconcile records means making them agree; ignoring discrepancies does not do that.','meaning'),[q('How did the neighbors reconcile?','they agreed to replace the damaged fence','they refused to speak about the dispute','they compared unrelated train schedules','邻居同意更换损坏篱笆后和解。',1,'context'),q('What did the accountant reconcile?','travel receipts and the expense ledger','the theater and the railway','two people after a quarrel','会计核对了差旅收据和费用账簿。',2,'context'),q('What did he reconcile himself to?','the old theater would not reopen','the theater had already reopened','the accountant had lost the receipts','他接受了老剧院不会重开的事实。',3,'context'),q('Which phrase means “accept a disappointing fact”?','reconcile oneself to it','reconcile it with the receipts','reconcile two neighbors','reconcile oneself to 表示接受不理想的事实。',3,'meaning')]);
P('reconciliation','Reconciliation is formed from reconcile and -ation; it is the process of restoring friendly relations or making conflicting ideas agree.',[C('reconciliation.s1','和解；调和','The reconciliation between the two departments began when their managers agreed on a shared schedule for the renovation.','两个部门的经理就翻修工程的共同日程达成一致后，双方开始和解。','The reconciliation began / when managers agreed / on a shared schedule.','reconciliation.s1 指争议双方恢复友好关系，也可指不同事物相互协调。','共同日程帮助两个部门缓和矛盾。')],M('The reconciliation failed because both departments agreed on a shared schedule and resolved every disagreement.','The reconciliation failed because the departments could not agree on a schedule and their conflict continued.','已经解决分歧并达成一致通常意味着和解成功，而非失败。','meaning'),[q('What began the departments’ reconciliation?','agreeing on a shared renovation schedule','opening a new railway line','recommending separate schedules forever','两个部门就翻修日程达成一致后开始和解。'),q('What is reconciliation?','restoring friendly relations or bringing ideas into agreement','a sudden backward movement','a letter praising an applicant','reconciliation 指恢复关系或使分歧协调一致。',1,'meaning'),q('Which phrase uses reconciliation naturally?','a reconciliation between the neighbors','a recline of the neighbors','a recognizable between the neighbors','a reconciliation between the neighbors 表示邻居之间的和解。',1,'collocation'),q('Which verb does reconciliation come from?','reconcile','recoil','recollect','reconciliation 由 reconcile 加 -ation 构成。',1,'word-formation')]);
P('reconsider','Reconsider combines re- and consider; it means think about a decision or plan again, often because new information has appeared.',C('reconsider.s1','重新考虑','The board agreed to reconsider the closure after residents presented evidence that the clinic served three remote villages.','居民提供证据说明诊所服务三个偏远村庄后，董事会同意重新考虑关闭决定。','The board agreed to reconsider the closure / after residents presented / new evidence.','reconsider 指重新审视原有决定或计划。','新证据促使董事会重审关闭方案。'),M('The board reconsidered the closure by refusing to review the decision or read the residents’ new evidence.','The board reconsidered the closure after reviewing the residents’ evidence.','重新考虑意味着重新审查，而不是拒绝查看新证据。','meaning'),[q('What did residents present to the board?','evidence about the clinic serving three villages','a recommendation letter for the railway','a receipt for a raincoat','居民提交了诊所服务三个村庄的证据。'),q('What did the board agree to do?','reconsider the clinic closure','close the clinic without review','rebuild the villages','董事会同意重新考虑关闭诊所。',1,'context'),q('When is someone likely to reconsider a plan?','when new evidence could change the decision','when they have already forgotten the plan','when they want to avoid thinking again','出现可能改变决定的新证据时，人们会重新考虑计划。',1,'meaning'),q('What does re- mean in reconsider?','again','against','together','re- 在 reconsider 中表示“再次”。',1,'word-formation')]);
P('reconstitute','Reconstitute combines re- and constitute, from Latin constituere “set up”; it means form a body again or restore a mixture by adding liquid.',C('reconstitute.s1','重新设立；复原','The research team reconstituted the powdered broth with warm water before using it to test the new sensor.','研究团队用温水复原粉末汤料，然后用它测试新传感器。','The team reconstituted the powder / with warm water / before testing the sensor.','reconstitute.s1 指从组成部分重新形成，也可指加液体恢复粉末混合物。','粉末加入温水后恢复成汤液。'),M('The cook reconstituted the powdered soup by keeping it dry and refusing to add any liquid.','The cook reconstituted the powdered soup by mixing it with the amount of water on the label.','复原粉末汤需要加入液体；保持干燥无法恢复成汤。','meaning'),[q('What did the team use to reconstitute the broth powder?','warm water','a railway schedule','a letter of recommendation','团队用温水复原汤粉。'),q('Why did they reconstitute the mixture?','to test the new sensor with the restored broth','to keep every ingredient dry','to close the remote clinic','团队复原汤料后用它测试传感器。',1,'context'),q('What does reconstitute mean for powdered food?','restore it by adding liquid','freeze it without changing its form','recommend it for a laboratory','粉末食品 reconstitute 指加液体复原。',1,'meaning'),q('Which prefix contributes the sense “again” in reconstitute?','re-','con-','-ute','re- 表示再次构成或恢复。',1,'word-formation')]);
P('reconstruct','Reconstruct combines re- and construct; it means rebuild something damaged or infer how a past event happened from evidence.',[C('reconstruct.s1','重建；复原','Engineers reconstructed the stone bridge using photographs and surviving blocks after the flood destroyed its center.','洪水毁坏石桥中央部分后，工程师依据照片和剩余石块重建了桥梁。','Engineers reconstructed the bridge / using photographs / and surviving blocks.','reconstruct.s1 指重新建造损坏的事物，也可根据证据推断过去经过。','工程师根据照片和残存石块重建桥梁。'),C('reconstruct.s1','还原经过；推断事件','Investigators reconstructed the train’s final minutes from the recorder, track marks and radio logs.','调查人员依据记录器、轨道痕迹和无线电日志还原了列车最后几分钟的经过。','Investigators reconstructed the final minutes / from recorder data / and track evidence.','reconstruct.s1 也可指根据证据推断某事如何发生。','多种记录帮助调查人员还原事故过程。')],M('Investigators reconstructed the crash by ignoring the recorder, track marks and radio logs and inventing an unsupported story.','Investigators reconstructed the crash by comparing recorder data with track marks and radio logs.','根据证据还原事件不能忽略证据、凭空编造。','meaning'),[q('What did engineers use to reconstruct the bridge?','photographs and surviving blocks','a recommendation letter and a timetable','rainwater and a railing','工程师用照片和残存石块重建桥梁。',1,'context'),q('What evidence helped investigators reconstruct the train’s final minutes?','recorder data, track marks and radio logs','a recluse’s childhood recollection','a rainfall chart alone','记录器、轨道痕迹和无线电日志帮助还原事故。',1,'context'),q('Which use of reconstruct means infer a past event?','reconstruct a crash from evidence','reconstruct a bridge from stone blocks','reconstruct a committee by appointing it','根据证据还原事故过程是“推断过去事件”。',1,'meaning'),q('Which two processes can reconstruct describe?','rebuilding an object and inferring an event','reclining and returning upright','recommending and recognizing','reconstruct 可指重建实物，也可指推断事件经过。',1,'meaning')]);
P('reconstruction','Reconstruction is formed from reconstruct and -ion; it can mean rebuilding after damage or forming an account of a past event or object.',[C('reconstruction.s1','重建；复建','The reconstruction of the old station preserved its stone façade while adding a safer platform for passengers.','旧车站重建时保留了石砌外立面，并为乘客增设了更安全的站台。','The reconstruction preserved the façade / while adding / a safer platform.','reconstruction.s1 指受损建筑或设施的重新建造。','车站复建兼顾了原有外观与安全。'),C('reconstruction.s2','复原；还原','The museum displayed a reconstruction of the ancient harbor based on maps, pottery and divers’ measurements.','博物馆展出了依据地图、陶器和潜水员测量结果复原的古代港口模型。','The museum displayed a reconstruction / based on maps, pottery / and underwater measurements.','reconstruction.s2 指依据证据重新构想过去的场景或物体。','多类证据帮助复原古港。')],M('The museum called its reconstruction evidence-based even though it used no maps, artifacts or measurements.','The museum based its reconstruction on maps, artifacts and measurements from the site.','历史复原需要依据证据；没有任何资料就不能称为有依据的重建。','meaning'),[q('What did the station reconstruction preserve?','the stone façade','the old unsafe platform exactly as it was','a railway timetable from another town','车站重建保留了石砌外立面。',1,'context'),q('What evidence supported the ancient harbor reconstruction?','maps, pottery and divers’ measurements','a single modern raincoat','unrelated radio advertisements','地图、陶器和潜水员测量支持了古港复原。',2,'context'),q('Which reconstruction is a physical rebuilding project?','repairing and restoring the old station','creating a model of an ancient harbor from evidence','remembering a station from childhood','修复旧车站属于实际建筑重建。',1,'meaning'),q('Which suffix helps form reconstruction from reconstruct?','-ion','-ive','-er','reconstruct 加 -ion 构成 reconstruction。',1,'word-formation')]);
P('record','Record comes from Old French recorder and Latin recordari, “remember”; it can mean stored information, a best achievement, a disc, a personal history, or the act of documenting.',[C('record.s1','记录；档案','The clinic kept a record of every vaccine dose so staff could check a patient’s history later.','诊所记录了每一剂疫苗，以便工作人员日后核查患者病史。','The clinic kept a record / of each vaccine dose / for later review.','record.s1 指为日后查阅而保存的文字或电子信息。','病历记录了患者接种情况。'),C('record.s2','纪录；最好成绩','The runner broke the national record by finishing the 1,500-meter race faster than anyone before her.','这名跑者以此前无人达到的速度完成1500米比赛，打破了全国纪录。','The runner broke the record / by finishing the race / faster than anyone before.','record.s2 指某项活动中曾达到的最佳成绩。','跑者创造了新的全国最佳成绩。'),C('record.s3','唱片','My grandfather played an old record on the turntable and told us where he had bought it.','祖父在唱机上播放一张旧唱片，并告诉我们当初在哪里买的。','My grandfather played a record / on the turntable / and told us its history.','record.s3 指储存音乐的圆形唱片。','唱片放在唱机上播放。'),C('record.s4','履历；前科','The hiring manager checked the applicant’s employment record before offering her the position.','招聘经理查看了申请人的工作履历，随后向她提供了职位。','The manager checked the employment record / before offering / the position.','record.s4 指某人的既往表现、经历或相关事实。','招聘经理核查了工作履历。'),C('record.s5','记录；录制','The camera recorded the station announcement so passengers could replay it later.','摄像设备录下了车站广播，方便乘客之后重听。','The camera recorded the announcement / so passengers / could replay it.','record.s5 作动词表示写下信息或保存声音、图像。','广播被设备录下来供之后播放。')],M('The clinic recorded each vaccine dose by deleting the patient’s file and keeping no information for later use.','The clinic recorded each vaccine dose in the patient’s file for later review.','记录信息要求保存可供日后查阅的数据，删除病历并不构成记录。','meaning'),[q('What did the clinic keep for future checks?','a record of each vaccine dose','a turntable for old music','a race medal only','诊所保存了每剂疫苗的记录。',1,'context'),q('What did the runner break?','the national 1,500-meter record','a vinyl record on a turntable','the applicant’s employment file','跑者打破了全国1500米纪录。',2,'context'),q('What did the grandfather play?','an old music record','a clinic record book','a race result on the camera','祖父在唱机上播放旧唱片。',3,'context'),q('Which sentence uses record as a verb meaning “capture sound”?','The camera recorded the station announcement.','The runner holds the national record.','The manager checked her employment record.','第一句中的 recorded 表示录下广播。',5,'meaning')]);
P('recorder','Recorder is formed from record and -er for a person or device; the musical instrument sense has a separate, older history whose deeper origin is uncertain.',[C('recorder.s1','记录员；记录仪','A recorder at the meeting entered each speaker’s name and decision in the official minutes.','会议记录员把每位发言者的姓名和决定记入正式纪要。','A recorder entered each name / and decision / in the official minutes.','recorder.s1 指记录信息的人或机器。','记录员整理了与会者发言和决定。'),C('recorder.s2','录音机；录像机','The reporter checked the digital recorder before interviewing the witness outside the station.','记者在车站外采访证人前检查了数字录音机。','The reporter checked the recorder / before interviewing / the witness.','recorder.s2 指保存声音或图像的设备。','记者确认录音设备正常。'),C('recorder.s3','竖笛；直笛','The child practiced a simple melody on the recorder while the teacher kept time on the piano.','老师用钢琴打拍子时，孩子用竖笛练习一段简单旋律。','The child practiced a melody / on the recorder / while the teacher kept time.','recorder.s3 指通过吹气演奏的管状木管乐器竖笛。','孩子在老师伴奏下练习竖笛。')],M('The student called the recorder a flute but played it by striking its keys with a hammer instead of blowing into it.','The student played the recorder by blowing into its mouthpiece to produce notes.','竖笛靠吹气发声，不是用锤子敲击琴键。','meaning'),[q('What did the meeting recorder enter in the minutes?','speakers’ names and decisions','the melody played by the child','the reporter’s interview audio','会议记录员记下发言者姓名和决定。',1,'context'),q('What did the reporter inspect before the interview?','a digital recorder','a railway ticket','a violin bow','记者采访前检查了数字录音机。',2,'context'),q('How did the child make music on the recorder?','by blowing into the instrument','by striking keys with a hammer','by turning a record on a turntable','孩子通过吹竖笛演奏旋律。',3,'context'),q('Which meaning of recorder is used in “the recorder entered the vote”?','a person who writes down information','a musical instrument','a device for capturing a video','这里 recorder 指负责记录信息的人。',1,'meaning')]);
P('recording','Recording is formed from record and -ing; it can name a saved sound or video, or the process of capturing it.',C('recording.s1','录制；录音录像','The archive restored a recording of the station opening, including the mayor’s speech and the first train announcement.','档案馆修复了一段车站开幕录音，其中包括市长讲话和首班列车广播。','The archive restored a recording / of the opening / with speeches and announcements.','recording.s1 指被保存下来的声音或图像材料。','录音保存了开幕讲话和列车广播。'),M('The archive called the recording a live event that had never been captured or saved in any form.','The archive called the recording a saved audio document from the station opening.','recording 可指被录下并保存的声音或影像，不是未被记录的现场活动。','meaning'),[q('What did the archive restore?','a recording of the station opening','a rectangular platform','a recommendation letter','档案馆修复了车站开幕录音。'),q('What could be heard in the recording?','the mayor’s speech and the first train announcement','a clinic’s vaccine record only','a violin lesson without any sound','录音包含市长讲话和首班车广播。',1,'context'),q('What can a recording preserve?','sound or video for later playback','only a person’s future plans','a train track’s physical shape','recording 可保存声音或影像供之后播放。',1,'meaning'),q('Which base verb forms recording?','record','recruit','recline','record 加 -ing 构成 recording。',1,'word-formation')]);
P('records','Records is the plural of record; it means stored written or digital information kept for later reference, especially about events or business.',C('records.s1','记录；档案','The hospital stored its records in a secure system so authorized doctors could review earlier treatments.','医院将病历保存在安全系统中，让获授权的医生能查看既往治疗。','The hospital stored its records / in a secure system / for authorized review.','records.s1 指保存下来供日后查阅的资料或档案。','医生可在安全系统中查看既往治疗记录。'),M('The hospital protected its records by erasing every treatment note before doctors could consult them.','The hospital protected its records by storing treatment notes securely for authorized doctors.','保存档案供获授权人员查询，不是把资料全部擦除。','meaning'),[q('Where did the hospital store its records?','in a secure system','on a public noticeboard','inside a patient’s raincoat','医院把病历保存在安全系统中。'),q('Who could review earlier treatments?','authorized doctors','any passerby at the station','only the person who wrote each note','获授权的医生可以查看既往治疗记录。',1,'context'),q('What does records mean here?','stored information kept for later reference','a collection of musical discs only','the act of setting a sports record','此处 records 指供以后查阅的资料档案。',1,'meaning'),q('What is records in relation to record?','its plural form','its past tense only','an adjective meaning recognizable','records 是 record 的复数形式。',1,'grammar')]);
P('recount','Recount combines re- and count; it can mean count votes again or tell the details of an event.',[C('recount.s1','重新计票','Election officials recounted the ballots after the margin fell below the threshold for an automatic review.','得票差距低于自动复核门槛后，选举官员重新清点了选票。','Officials recounted the ballots / after the margin fell / below the review threshold.','recount.s1 作动词指再次清点选票或物品。','选票差距触发了重新计票。'),C('recount.s2','讲述；叙述','The guide recounted how the old bridge survived the flood while leading visitors along the river.','导游带领游客沿河而行时，讲述了旧桥如何挺过洪水。','The guide recounted the bridge’s story / while leading visitors / along the river.','recount.s2 指按顺序讲述一段经历或事件。','导游讲述了桥梁幸存的经历。')],M('Officials recounted the ballots by counting each one exactly once and refusing to repeat the tally.','Officials recounted the ballots by conducting a second count after the close margin.','重新计票必须再数一遍选票，而不是只进行一次计数。','meaning'),[q('Why did officials recount the ballots?','the margin triggered a review','the bridge had survived a flood','the guide lost a recording','得票差距触发了重新计票。',1,'context'),q('What did the guide recount to visitors?','how the bridge survived the flood','the number of ballots in an election','the recipe for a powdered soup','导游讲述了旧桥如何挺过洪水。',2,'context'),q('Which meaning is used in “recount the votes”?','count them again','describe a past event','regain money after a loss','recount votes 指重新计票。',1,'meaning'),q('Which meaning is used in “recount the journey”?','tell the details of an event','count the passengers a second time','make a bridge friendly again','recount a journey 指讲述旅程经过。',2,'meaning')]);
P('recoup','Recoup came through French recouper, “to cut back”; it now means regain money or make up for a loss.',C('recoup.s1','挽回损失；收回成本','The theater hoped to recoup renovation costs through ticket sales during the first year.','剧院希望通过第一年的售票收入收回翻修成本。','The theater hoped to recoup its costs / through ticket sales / during the first year.','recoup 指重新获得已花费或损失的钱，也可弥补损失。','票房收入有望收回翻修成本。'),M('The theater recouped its renovation costs by spending more money and earning no ticket revenue.','The theater recouped its renovation costs by earning enough from ticket sales.','没有收入且继续支出，不能算收回成本。','meaning'),[q('How did the theater hope to recoup its costs?','through ticket sales','by closing the building permanently','by deleting its renovation records','剧院希望通过售票收回翻修成本。'),q('When did it hope to recover the costs?','during the first year','before construction began','after the building was demolished','剧院计划第一年收回成本。',1,'context'),q('What does recoup mean?','regain money or make up for a loss','count votes a second time','restore friendly relations','recoup 表示收回支出或弥补损失。',1,'meaning'),q('Which phrase uses recoup naturally?','recoup the cost of repairs','recoup the chair backward','recoup an interview into a recording','recoup repair costs 表示收回维修成本。',1,'collocation')]);
P('recourse','Recourse comes from Latin recursus, “a running back,” through French; it means a source of help or action one can turn to when needed.',C('recourse.s1','求助；求助的对象','When the landlord refused to repair the heater, the tenants had recourse to the housing tribunal.','房东拒绝修暖气后，租户向住房仲裁庭寻求帮助。','The tenants had recourse to the tribunal / when the landlord / refused repairs.','recourse 指遇到困难时可以求助的手段、机构或人。','租户向仲裁机构寻求解决办法。'),M('The tenants had recourse to the tribunal by avoiding every available source of help and refusing to file a complaint.','The tenants had recourse to the tribunal by filing a complaint for help.','求助于机构意味着利用可用的救济途径，而不是拒绝寻求帮助。','meaning'),[q('Why did the tenants seek recourse?','the landlord refused to repair the heater','their ballots needed another count','they wanted a new musical recording','房东拒绝维修暖气后，租户寻求帮助。'),q('Where did they turn for recourse?','the housing tribunal','the theater ticket office','the railway railhead','租户向住房仲裁庭求助。',1,'context'),q('What is recourse?','a source of help one can turn to','a record of a sports achievement','a process for crystallizing a solution','recourse 指可求助的途径或对象。',1,'meaning'),q('Which phrase is idiomatic?','have recourse to the courts','have recourse from the courts into a record','do recourse the ballots again','have recourse to the courts 是自然搭配。',1,'collocation')]);
P('recover','Recover came through Old French recoverer from Latin recuperare, “get back”; it can mean regain health, return to normal, or find something lost.',[C('recover.s1','痊愈；恢复健康','After the operation, Mei recovered steadily and returned to work when her doctor cleared her.','手术后，梅稳步康复，并在医生许可后重返工作岗位。','Mei recovered steadily / after the operation / and returned to work.','recover.s1 指疾病或受伤后恢复健康。','医生确认梅康复后，她重返工作。'),C('recover.s2','恢复（状态、情绪）','The server recovered from the brief outage and began processing queued orders again.','服务器从短暂故障中恢复后，重新开始处理排队订单。','The server recovered from the outage / and resumed processing / queued orders.','recover.s2 指回到正常状态或功能。','服务器恢复运行并继续处理订单。'),C('recover.s3','重新获得；找回','The hikers recovered the lost map from beneath a bench near the trail entrance.','徒步者在步道入口附近的长椅下找回了丢失的地图。','The hikers recovered the map / from beneath a bench / near the trail entrance.','recover.s3 指重新得到丢失或被拿走的东西。','徒步者找回地图。')],M('The server recovered from the outage by remaining offline and refusing to process any queued orders.','The server recovered from the outage and resumed processing the queued orders.','恢复正常功能应重新运行；继续离线并拒绝处理任务不是恢复。','meaning'),[q('When did Mei return to work?','after her doctor cleared her following surgery','before the operation began','when the lost map was recovered','医生确认梅术后康复后，她返回工作。',1,'context'),q('What did the server do after it recovered?','processed queued orders again','remained offline permanently','searched under a trail bench','服务器恢复后继续处理排队订单。',2,'context'),q('Where did the hikers recover the map?','under a bench near the trail entrance','inside the theater ticket box','from the hospital records','徒步者在步道入口附近的长椅下找回地图。',3,'context'),q('Which sense of recover is used in “recover a stolen wallet”?','get back something lost','become well after illness','return to normal operation','recover a stolen wallet 指找回失物。',3,'meaning')]);
P('recovery','Recovery is formed from recover and -y; it means a return to health or to a normal condition after difficulty.',C('recovery.s1','恢复；痊愈','The patient’s recovery took several weeks, and she followed the therapist’s exercises at home each day.','患者用了几周才康复，并每天在家按治疗师要求锻炼。','The patient’s recovery took weeks / as she followed / daily exercises.','recovery.s1 指疾病或困难之后重新达到正常状态的过程。','患者通过持续锻炼逐渐康复。'),M('The doctor called it a full recovery even though the patient’s symptoms had worsened and normal activity remained impossible.','The doctor called it a recovery after the patient’s symptoms eased and normal activity resumed.','病情持续恶化且无法恢复正常活动，不属于康复。','meaning'),[q('How long did the patient’s recovery take?','several weeks','one minute before the injury','a year before any treatment','患者花了几周恢复。'),q('What did she do during recovery?','followed the therapist’s daily exercises','stopped all movement forever','recounted a distant election','患者每天按治疗师要求锻炼。',1,'context'),q('What does recovery mean after illness?','a return to health or normal condition','a sudden attack on a place','a letter recommending a candidate','疾病后的 recovery 指恢复健康或正常状态。',1,'meaning'),q('Which phrase is natural?','make a gradual recovery','make a recovery the votes again','make a recluse recovery to the station','make a gradual recovery 是自然搭配。',1,'collocation')]);
P('recreant','Recreant came through Old French for someone who had yielded or abandoned a duty; it now describes cowardly or disloyal failure to meet an obligation.',C('recreant.s1','怯懦不忠的','The captain condemned the recreant guard who deserted the post during the emergency.','队长谴责了那名在紧急情况下擅离岗位的怯懦卫兵。','The captain condemned the recreant guard / who deserted / the post during the emergency.','recreant 描写因怯懦或背弃职责而失职的人或行为。','卫兵在紧急时刻抛下岗位，违背职责。'),M('The captain called the guard recreant because he stayed at his post and protected the people during the emergency.','The captain called the guard recreant because he abandoned his post during the emergency.','坚守岗位保护他人是履行职责，不是怯懦背弃职责。','meaning'),[q('Why did the captain condemn the guard?','he deserted his post during an emergency','he recovered the station’s lost records','he recommended a new guard','队长因卫兵紧急时擅离岗位而谴责他。'),q('What does recreant describe?','cowardly or disloyal failure of duty','a person who is easy to recognize','a gradual return to health','recreant 指怯懦或不忠而未履行职责。',1,'meaning'),q('Which behavior is recreant?','abandoning a duty out of cowardice','remaining at a post to protect others','admitting an error and correcting it','因怯懦而抛弃职责属于 recreant 行为。',1,'context'),q('Which older idea is associated with recreant?','yielding or abandoning a duty','forming a rectangle','recording sound','recreant 的旧义涉及屈服或背弃职责。',1,'word-formation')]);
P('recreate','Recreate combines re- and create; it means make something exist again or copy it closely from evidence or a model.',C('recreate.s1','再创造；再现','The museum team recreated the workshop using old photographs, tools and notes from the original carpenter.','博物馆团队依据旧照片、工具和原木匠的笔记，再现了当年的作坊。','The team recreated the workshop / using old photographs / tools and notes.','recreate.s1 指重新制造某物或尽量准确地复现原貌。','团队依据多种资料再现了旧作坊。'),M('The museum recreated the workshop by removing every tool and photograph and leaving an empty room.','The museum recreated the workshop by arranging period tools according to photographs and notes.','再现作坊需要依据资料重建其样貌，而不是清空房间。','meaning'),[q('What did the museum team recreate?','the carpenter’s workshop','the carpenter’s recommendation letter','a new recruitment campaign','团队再现了木匠的作坊。'),q('What sources did the team use?','photographs, tools and the carpenter’s notes','only a modern railway timetable','unrelated rainfall records','团队依据照片、工具和笔记进行复原。',1,'context'),q('What does recreate mean here?','make something exist again or copy it closely','rest after a difficult day','hire a new worker','recreate 指再造或逼真复现。',1,'meaning'),q('What does re- contribute to recreate?','again','against','afterwards only','re- 在 recreate 中表示“再次、重新”。',1,'word-formation')]);
P('recreation','Recreation comes through French from Latin recreatio, “restoration or refreshment”; it means an enjoyable activity or the general use of free time for relaxation.',[C('recreation.s1','娱乐；消遣活动','Kayaking became their favorite recreation after work because the quiet river helped them unwind.','下班后划皮艇成了他们最喜欢的消遣，因为平静的河流让他们放松。','Kayaking became their recreation / after work / because it helped them unwind.','recreation.s1 指人们闲暇时为乐趣而从事的活动。','划皮艇是他们下班后的消遣。'),C('recreation.s2','娱乐；休闲活动（总称）','The town invested in recreation by adding public trails, playgrounds and an indoor pool.','小镇通过修建公共步道、游乐场和室内泳池来发展休闲活动。','The town invested in recreation / by adding trails / playgrounds and a pool.','recreation.s2 指放松、享受闲暇的活动或其总体领域。','小镇增设多种设施以供休闲。')],M('The town funded recreation by closing every trail, playground and pool so residents had nowhere to relax.','The town funded recreation by maintaining trails, playgrounds and a public pool.','休闲设施应提供放松活动；关闭所有设施与目的相反。','meaning'),[q('What was their favorite recreation after work?','kayaking on the quiet river','recounting ballots at the office','rebuilding the old station','他们下班后喜欢划皮艇消遣。',1,'context'),q('How did the town invest in recreation?','by adding trails, playgrounds and a pool','by closing every public activity space','by cutting the railway from the map','小镇增建步道、游乐场和泳池来发展休闲活动。',2,'context'),q('Which is an example of recreation?','playing a game for enjoyment in free time','working a compulsory night shift','recounting official ballots','闲暇时为了乐趣进行的游戏属于 recreation。',1,'meaning'),q('What did Latin recreatio suggest?','restoration or refreshment','cowardice or desertion','a four-sided shape','recreation 源自表示“恢复、提神”的拉丁语。',1,'word-formation')]);
P('recreational','Recreational is formed from recreation and -al; it describes activity or equipment intended for leisure, including amateur pursuits.',[C('recreational.s1','娱乐的；休闲的','The city opened a recreational trail beside the lake for walking, cycling and birdwatching.','市政府在湖边开放了一条休闲步道，供人们散步、骑行和观鸟。','The city opened a recreational trail / beside the lake / for several leisure activities.','recreational.s1 表示供休闲娱乐使用的。','湖边步道供居民休闲活动。'),C('recreational.s2','业余消遣的','He joined a recreational rowing club, where members practiced for enjoyment rather than professional competition.','他加入了一个业余划船俱乐部，成员训练是为了娱乐而非职业比赛。','He joined a recreational rowing club / whose members rowed / for enjoyment, not a career.','recreational.s2 指为兴趣而做、并非职业工作的活动。','俱乐部成员划船是为了消遣。')],M('The city called the trail recreational even though it was closed to walkers, cyclists and every other leisure user.','The city called the trail recreational because residents could walk, cycle and watch birds there.','休闲步道应供居民开展娱乐活动，而不是完全禁止使用。','meaning'),[q('What activities can people do on the lakeside trail?','walk, cycle and watch birds','recount ballots and recruit staff','record a radio drama','步道可供散步、骑行和观鸟。',1,'context'),q('Why did members join the rowing club?','to row for enjoyment rather than a career','to recover a damaged railway','to record official minutes','俱乐部成员划船是为了娱乐，不是职业比赛。',2,'context'),q('Which is a recreational activity?','a weekend paddle for fun','a required work shift','a medical operation','周末为了乐趣划船属于休闲活动。',1,'meaning'),q('Which noun is recreational formed from?','recreation','recovery','recruitment','recreational 由 recreation 加 -al 构成。',1,'word-formation')]);
P('recruit','Recruit came through French recruter, first used for obtaining fresh troops; it can mean enlist or hire new people, or name a newly joined member.',[C('recruit.s1','招募；招收','The hospital recruited two nurses for the night shift after patient numbers increased.','患者数量增加后，医院为夜班招募了两名护士。','The hospital recruited two nurses / for the night shift / after demand increased.','recruit.s1 作动词表示招募新成员加入组织或职位。','医院因需求上升招募夜班护士。'),C('recruit.s2','新兵；新成员','Each recruit received safety training before joining the mountain rescue team.','每名新队员加入山地救援队前都接受了安全培训。','Each recruit received training / before joining / the rescue team.','recruit.s2 指刚加入机构或团体的人，尤指新兵。','新队员先接受培训再执行任务。')],M('The hospital recruited new nurses by dismissing applicants and refusing to invite anyone to join the staff.','The hospital recruited new nurses by selecting applicants and inviting them to join the staff.','招募是邀请新成员加入，不是拒绝所有申请者。','meaning'),[q('Why did the hospital recruit nurses?','patient numbers had increased','the old station had been reconstructed','the theater wanted to recoup costs','患者数量增加促使医院招募护士。',1,'context'),q('What did each rescue-team recruit receive?','safety training','a letter of recommendation only','a new railway ticket','新队员接受了安全培训。',2,'context'),q('Which meaning is used in “recruit volunteers”?','find new people to join','a person who has just joined','recover something lost','recruit volunteers 作动词表示招募志愿者。',1,'meaning'),q('Which meaning is used in “the newest recruit”?','a newly joined member','the act of hiring','a way to restore health','the newest recruit 指刚加入的新成员。',2,'meaning')]);
P('recruitment','Recruitment is formed from recruit and -ment; it means finding and bringing new people into a company, organization or the armed forces.',[C('recruitment.s1','招聘；招募','The firm expanded its recruitment campaign to attract engineers with experience in battery recycling.','公司扩大了招聘活动，以吸引有电池回收经验的工程师。','The firm expanded recruitment / to attract experienced engineers / in battery recycling.','recruitment.s1 指为公司或组织寻找并招收新成员。','公司扩大招聘以补充专业工程师。'),C('recruitment.s2','征兵；征募','The country revised military recruitment rules and raised the minimum age for voluntary enlistment.','该国修订了征兵规定，并提高了自愿入伍的最低年龄。','The country revised military recruitment rules / and raised / the enlistment age.','recruitment.s2 指为军队征募人员。','政府调整了军队征募规定。')],M('The firm called its recruitment campaign a process of hiring no one and keeping every position vacant.','The firm called its recruitment campaign an effort to find and hire qualified engineers.','recruitment 是寻找并招收人员，不是让职位一直空缺。','meaning'),[q('What experience did the firm seek in candidates?','battery recycling','musical recording','railway reconstruction','公司招聘有电池回收经验的工程师。',1,'context'),q('What military rule did the country revise?','the minimum age for voluntary enlistment','the size of a rectangle','the number of clinic records','该国调整了自愿入伍年龄规定。',2,'context'),q('What does recruitment mean in a company?','finding and bringing in new employees','training only existing staff','restoring a patient to health','公司 recruitment 指寻找并招收新员工。',1,'meaning'),q('Which suffix forms recruitment from recruit?','-ment','-able','-ly','recruit 加 -ment 构成 recruitment。',1,'word-formation')]);
P('recrystallize','Recrystallize combines re- and crystallize; in chemistry it means dissolve a substance and let it form crystals again, often to purify it.',C('recrystallize.s1','使再结晶；再结晶','The chemist recrystallized the impure solid from hot solvent and collected cleaner crystals after cooling.','化学家把不纯固体溶于热溶剂，再冷却析出较纯的晶体。','The chemist recrystallized the solid / from hot solvent / and collected cleaner crystals.','recrystallize 指物质溶解后重新形成晶体，常用于提纯。','冷却后析出的晶体更纯。'),M('The chemist recrystallized the sample by melting it into a gas and never allowing any crystals to form again.','The chemist recrystallized the sample by dissolving it and allowing crystals to form as it cooled.','再结晶需要重新形成晶体，不能让样品一直保持气态。','meaning'),[q('What did the chemist do with the impure solid?','dissolved it in hot solvent and cooled it','recorded its mass without changing it','recruited it into a laboratory team','化学家将固体溶解后冷却再结晶。'),q('Why was the solid recrystallized?','to collect cleaner crystals','to prevent any crystals from forming','to recover a lost train record','再结晶可获得更纯的晶体。',1,'context'),q('What does recrystallize mean?','form crystals again after dissolving','turn a rectangle into a circle','hire a new chemist','recrystallize 指溶解后再次形成晶体。',1,'meaning'),q('What does re- mean in recrystallize?','again','below','without','re- 表示晶体再次形成。',1,'word-formation')]);
P('rectangle','Rectangle combines Latin rectus, “right or straight,” with angulus, “angle”; it is a flat four-sided shape with four right angles.',C('rectangle.s1','长方形；矩形','The architect drew a rectangle for the classroom floor plan, marking each corner as a right angle.','建筑师在教室平面图上画了一个矩形，并把每个角标为直角。','The architect drew a rectangle / with four corners / marked as right angles.','rectangle.s1 指四条直边、四个角均为直角的平面图形。','图中的四个角都是直角。'),M('The architect called a three-sided shape with one curved edge a rectangle because it had a right angle.','The architect called the four-sided shape a rectangle because all four corners were right angles.','一个直角还不够；矩形必须有四条直边和四个直角。','meaning'),[q('What shape did the architect draw?','a four-sided figure with four right angles','a three-sided figure with one curve','a circle with a measured radius','建筑师画了四个角均为直角的四边形。'),q('How many right angles does a rectangle have?','four','one','none','矩形有四个直角。',1,'meaning'),q('Which shape is a rectangle?','a flat four-sided shape with four right corners','a three-sided figure with one curved side','a circle with no corners','四条直边、四个直角的平面图形是矩形。',1,'meaning'),q('What do the Latin parts of rectangle refer to?','right and angle','record and sound','recruit and group','rectangle 的拉丁词根分别与“直角”和“角”有关。',1,'word-formation')]);
P('rectangular','Rectangular is formed from rectangle and -ar; it describes a shape like a rectangle or, in geometry, something meeting at a right angle.',[C('rectangular.s1','矩形的','A rectangular skylight brought daylight into the kitchen without taking up the entire roof.','一扇矩形天窗把自然光引入厨房，又没有占据整片屋顶。','A rectangular skylight brought daylight / into the kitchen / without covering the whole roof.','rectangular.s1 表示具有矩形形状的。','天窗呈矩形，为厨房引入日光。'),C('rectangular.s2','成直角的','The two rectangular beams met at a right angle, forming a stable corner in the frame.','两根相互垂直的梁成直角相交，构成框架中稳固的拐角。','The beams met at a right angle / and formed / a stable frame corner.','rectangular.s2 可表示以直角相交或垂直的。','梁以直角相交。')],M('The carpenter described the beams as rectangularly joined even though they met at a sharp acute angle.','The carpenter described the beams as meeting at a right angle.','成直角表示90度；锐角小于90度。','meaning'),[q('What shape was the kitchen skylight?','rectangular','circular','triangular','厨房的天窗是矩形的。',1,'context'),q('At what angle did the beams meet?','a right angle','a straight line with no corner','an acute angle under ninety degrees','两根梁成直角相交。',2,'context'),q('Which object is rectangular?','a four-cornered window with right angles','a round plate','a triangular sign','四角均为直角的窗户是矩形的。',1,'meaning'),q('Which suffix appears in rectangular?','-ar','-ment','-ize','rectangular 由 rectangle 加 -ar 构成。',1,'word-formation')]);
P('rectify','Rectify comes from Latin rectificare, “make straight or right”; it means correct an error, and in electronics it means convert alternating current to direct current.',[C('rectify.s1','纠正；改正','The editor rectified the date in the report after checking the signed minutes from the meeting.','核对会议签字纪要后，编辑纠正了报告中的日期。','The editor rectified the date / after checking / the signed minutes.','rectify.s1 指纠正错误或使不当之处改正。','编辑依据正式纪要更正日期。'),C('rectify.s2','整流；交流转直流','A diode rectifies the alternating current from the generator before it reaches the battery.','发电机的交流电到达电池前由二极管整流。','A diode rectifies the current / before it reaches / the battery.','rectify.s2 在电子学中指把交流电转换成直流电。','二极管在电流进入电池前完成整流。')],M('The editor rectified the report by leaving the incorrect date unchanged and deleting the signed evidence.','The editor rectified the report by correcting the date to match the signed minutes.','rectify 表示改正错误；保留错日期并删掉证据没有改正问题。','meaning'),[q('What did the editor rectify?','the report’s date','the battery’s rectangular casing','the company’s recruitment policy','编辑纠正了报告中的日期。',1,'context'),q('What does the diode do to the current?','converts alternating current to direct current','recounts it a second time','recruits it into the battery','二极管把交流电整流为直流电。',2,'context'),q('Which use of rectify means “correct an error”?','rectify an incorrect date','rectify alternating current','rectify a right angle into a rectangle','rectify a date 表示纠正日期错误。',1,'meaning'),q('Which use is technical and electrical?','rectify AC before it reaches a battery','rectify a typo in a report','rectify an argument between colleagues','电子学中的 rectify 指交流电转换成直流电。',1,'meaning')]);
P('recuperate','Recuperate comes from Latin recuperare, “to get back”; it means recover health or regain money, strength or another loss.',[C('recuperate.s1','康复；恢复健康','The cyclist recuperated at home for a month after the crash before returning to long-distance training.','事故后，这名骑行者在家休养了一个月，才恢复长距离训练。','The cyclist recuperated at home / for a month / before training again.','recuperate.s1 指疾病或受伤后恢复健康和体力。','骑行者休养后重新训练。'),C('recuperate.s2','挽回；收回','The small publisher recuperated some of its losses when the revised textbook sold well the following term.','修订版教材在下一学期畅销后，小型出版社挽回了部分损失。','The publisher recuperated some losses / when the revised textbook / sold well.','recuperate.s2 指重新获得损失的钱或体力。','教材畅销帮助出版社收回部分损失。')],M('The cyclist recuperated from the crash by training continuously through severe pain and allowing no time for healing.','The cyclist recuperated by resting until the injury healed before returning to training.','伤后康复需要身体恢复，持续带伤训练并不表示已康复。','meaning'),[q('How long did the cyclist recuperate at home?','a month','one afternoon before the crash','a year of uninterrupted racing','骑行者在家休养了一个月。'),q('What helped the publisher recuperate its losses?','strong sales of the revised textbook','closing the bookstore permanently','losing more money on the new edition','修订版教材畅销帮助出版社挽回损失。',2,'context'),q('Which meaning is used in “recuperate after surgery”?','recover health and strength','regain money from sales','correct a date in a report','recuperate after surgery 指术后康复。',1,'meaning'),q('Which meaning is used in “recuperate the investment”?','win back money that was spent','recover from a fever','rebuild a damaged bridge','recuperate the investment 指挽回投资成本。',2,'meaning')]);
P('recur','Recur comes from Latin recurrere, “to run back”; it means happen again or, of a thought, return repeatedly to the mind.',[C('recur.s1','再发生；复发','If the leak recurs after the pipe is sealed, call the building manager rather than covering the stain again.','管道封好后如果漏水再次发生，应联系物业经理，而不是再把污渍盖住。','If the leak recurs / after the pipe is sealed / call the manager.','recur.s1 指某事再次发生，常带有反复或复发意味。','漏水再次发生时要进一步维修。'),C('recur.s2','（想法）反复浮现','The image of the damaged bridge recurred in his mind whenever heavy rain began.','每逢大雨开始，受损桥梁的画面就会在他脑海里反复浮现。','The image recurred in his mind / whenever heavy rain / began.','recur.s2 指念头或记忆反复进入意识。','大雨让他反复想起受损的桥。')],M('The leak recurred only once in the past, so the sentence says it can never happen again.','The leak recurred after the repair, meaning it happened again.','recur 表示再次发生，不能据此推断以后绝不会再发生。','meaning'),[q('What should residents do if the leak recurs?','call the building manager','cover the stain and ignore the pipe','recount the meeting minutes','漏水再次发生时应联系物业经理。',1,'context'),q('When did the bridge image recur in his mind?','whenever heavy rain began','only when the bridge was rebuilt','after he forgot the whole event','每次大雨开始，他就想起受损桥梁。',2,'context'),q('What does recur mean of a problem?','happen again','be corrected permanently','be recorded for the first time','问题 recur 表示再次发生。',1,'meaning'),q('What does recur mean of a thought?','return repeatedly to the mind','move backward after a shot','be divided into equal shares','想法 recur 指反复浮现。',2,'meaning')]);
P('recurrence','Recurrence is formed from recur and -ence; it means another occurrence of something that has happened before.',C('recurrence.s1','再发生；复发','The recurrence of the power failure prompted the hospital to install a backup generator.','停电再次发生后，医院决定安装备用发电机。','The recurrence of the outage / prompted the hospital / to install backup power.','recurrence.s1 指先前发生过的事件又一次出现。','停电复发促使医院增设备用电源。'),M('The hospital described the recurrence as impossible because the power failure happened again for a second time.','The hospital called the second power failure a recurrence and installed backup power.','事件再次发生正是 recurrence 的含义。','meaning'),[q('What prompted the hospital to install a generator?','the recurrence of power failures','a single successful backup test','the recruitment of nurses','停电再次发生促使医院安装发电机。'),q('What is a recurrence?','another occurrence of something that happened before','the first occurrence of a new event','a recommendation letter','recurrence 指某事再次发生。',1,'meaning'),q('Which phrase is natural?','a recurrence of the same error','a recurrence of the error before it ever happened','a recurrence that never occurred again','a recurrence of the same error 表示同一错误再次出现。',1,'collocation'),q('Which word is recurrence based on?','recur','recluse','record','recurrence 由 recur 加 -ence 构成。',1,'word-formation')]);
P('recurrent','Recurrent comes from Latin recurrens, “running back”; it describes something that happens repeatedly rather than only once.',C('recurrent.s1','反复发生的；周期性的','The clinic scheduled extra checks for patients with recurrent infections that returned several times a year.','诊所为一年中反复感染数次的患者安排了额外检查。','The clinic scheduled checks / for recurrent infections / returning several times a year.','recurrent 描述一再出现或周期性发生的情况。','感染一年复发数次，因此需要额外检查。'),M('The doctor called the infection recurrent even though it happened once and never returned.','The doctor called the infection recurrent because it returned several times during the year.','只发生一次且从不复发不符合 recurrent 的反复性。','meaning'),[q('How often did the patients’ infections return?','several times a year','once and never again','every minute without stopping','患者的感染一年复发数次。'),q('What does recurrent mean?','happening repeatedly','happening only once','being easy to identify','recurrent 指反复发生的。',1,'meaning'),q('Which is a recurrent problem?','a monthly system outage','a single outage that never returns','a problem corrected before it occurs','每月出现的系统故障属于反复问题。',1,'context'),q('Which word is related to recurrent?','recur','rectangle','redeem','recurrent 与 recur“再次发生”同源。',1,'word-formation')]);
P('recurring','Recurring is the -ing form of recur; it describes something that appears again, often regularly or as a repeated theme.',C('recurring.s1','一再发生的；反复出现的','A recurring reminder appears on her calendar every Friday so she remembers to submit the weekly report.','她的日历上每周五都会出现一个重复提醒，让她记得提交周报。','A recurring reminder appears / every Friday / before the report is due.','recurring 描述不断重现或按固定周期再现的事物。','提醒每周五重复出现。'),M('The calendar alert was called recurring even though it appeared once and was deleted before the next Friday.','The calendar alert was recurring because it appeared every Friday.','只出现一次并删除的提醒不是定期重复的。','meaning'),[q('When does the calendar reminder appear?','every Friday','once on the first day only','only after the report is submitted','提醒每周五出现。'),q('What does recurring mean?','appearing again, often on a schedule','never happening more than once','having a red color','recurring 指反复出现，常按固定时间安排。',1,'meaning'),q('Which is a recurring payment?','a subscription charge each month','a one-time fee with no repeat','a refund that is never collected','每月收取的订阅费是 recurring payment。',1,'context'),q('What is the base verb of recurring?','recur','recruit','recount','recurring 是 recur 的 -ing 形式。',1,'grammar')]);
P('recycle','Recycle combines re- and cycle; it means process waste so its materials can be used again, or reuse an idea or object in a new way.',[C('recycle.s1','回收利用','The city recycles glass bottles into new containers instead of sending them to the landfill.','市政府把玻璃瓶回收制成新容器，而不是送进填埋场。','The city recycles glass bottles / into new containers / instead of landfilling them.','recycle.s1 指处理废弃材料，使其重新用于生产。','旧瓶被制成新的容器。'),C('recycle.s2','再次运用；重新利用','The designer recycled an old poster layout for the school’s new music festival, changing its colors and text.','设计师把旧海报版式改换颜色和文字后，用在学校的新音乐节宣传中。','The designer recycled the layout / for a new festival poster / with changed colors and text.','recycle.s2 指以新方式再次使用旧想法或材料。','旧版式经改造后用于新海报。')],M('The city recycled glass bottles by crushing them and burying the pieces permanently without processing or reuse.','The city recycled the glass by processing it into material for new containers.','填埋废玻璃而不处理再利用，不属于回收利用。','meaning'),[q('What did the city make from old glass bottles?','new containers','a recruitment letter','a rectangular bridge','市政府把旧玻璃瓶制成新容器。',1,'context'),q('How did the designer recycle the poster layout?','changed its colors and text for a new festival','copied it unchanged and called it a new idea','threw it away before designing anything','设计师改换颜色和文字后再次使用旧版式。',2,'context'),q('Which action is material recycling?','processing used glass so it can become new products','burying all glass in a landfill','collecting records without using them again','把废玻璃加工成新产品属于回收利用。',1,'meaning'),q('Which action is figurative reuse?','recycle an old idea in a new campaign','send glass bottles to a landfill','count votes a second time','把旧想法用于新宣传活动是比喻用法。',2,'meaning')]);
P('recycling','Recycling is formed from recycle and -ing; it is the collection and processing of waste so its materials can re-enter production.',C('recycling.s1','循环利用','The school expanded recycling by placing clearly labeled bins for paper, cans and clean plastic bottles.','学校增设了标识清楚的纸张、易拉罐和洁净塑料瓶回收箱，以扩大循环利用。','The school expanded recycling / by adding labeled bins / for reusable materials.','recycling.s1 指收集并处理废弃物，使材料重新进入生产流程。','分类回收箱帮助学生收集可再利用材料。'),M('The school increased recycling by mixing paper, cans and plastic with food waste and sending everything to a landfill.','The school increased recycling by sorting paper, cans and clean plastic for processing.','把材料混在一起送去填埋不会让它们重新进入生产流程。','meaning'),[q('What did the school add to support recycling?','labeled bins for paper, cans and plastic','a single bin for mixed landfill waste','a new recording studio','学校增设了分类回收箱。'),q('What happens to materials in recycling?','they are processed so they can be used again','they are buried permanently without sorting','they are turned into a recurring reminder','回收材料会经过处理并再次利用。',1,'meaning'),q('Which item should go in the described recycling bins?','a clean plastic bottle','a bowl of leftover soup','a broken battery mixed with food','描述中的回收箱收集洁净塑料瓶。',1,'context'),q('What word is recycling formed from?','recycle','recluse','recovery','recycling 是 recycle 加 -ing 构成。',1,'word-formation')]);
P('red','Red comes from Old English rēad; it names a color and can describe a flushed face or, in financial language, a loss shown in red ink.',[C('red.s1','红色的','The red warning light flashed above the door when the temperature in the storage room rose too high.','储藏室温度过高时，门上方的红色警示灯闪烁起来。','The red warning light flashed / when the room temperature / rose too high.','red.s1 指血液或成熟番茄常见的红色。','红灯提示储藏室温度过高。'),C('red.s2','涨红的；充血的','His eyes were red after he spent the night reading the emergency reports.','他通宵阅读紧急报告后，眼睛都熬红了。','His eyes were red / after he spent the night / reading reports.','red.s2 可形容因疲倦、情绪或充血而变红的脸或眼睛。','熬夜使他的眼睛发红。'),C('red.s3','红色','The painter mixed red with white to produce a softer shade for the theater wall.','画家把红色与白色混合，为剧院墙面调出较柔和的色调。','The painter mixed red with white / to produce / a softer shade.','red.s3 作名词指红这种颜色。','调色时把红色与白色混合。'),C('red.s4','赤字；负债','The shop was in the red after repair costs exceeded its sales for three months.','维修费用连续三个月超过销售额后，这家商店出现了亏损。','The shop was in the red / after repair costs exceeded / its sales.','red.s4 在财务表达 in the red 中指亏损或负债。','支出超过收入导致商店亏损。')],M('The shop was in the red because its sales exceeded every cost and it earned a large profit.','The shop was in the red because its costs exceeded its sales and it lost money.','in the red 指亏损，不是收入超过成本的盈利状态。','meaning'),[q('What did the red warning light indicate?','the storage room was too warm','the store had earned a profit','the painter needed more white paint','红灯表示储藏室温度过高。',1,'context'),q('Why were his eyes red?','he had spent the night reading reports','he had just repainted a wall','the shop was in the red','通宵阅读让他的眼睛发红。',2,'context'),q('What did the painter mix with white?','red','blue','black','画家把红色与白色混合。',3,'context'),q('What does “the shop was in the red” mean?','it was losing money','it was earning a large profit','its walls were painted red','in the red 表示财务亏损。',4,'meaning')]);
P('redbud','Redbud combines red and bud; it is the common name for a deciduous tree whose reddish flowers cluster on bare branches in spring.',C('redbud.s1','美国紫荆','Pink-red flowers appeared along the bare branches of the redbud before its heart-shaped leaves opened.','紫荆叶片尚未展开前，粉红色花朵已经缀满光秃枝条。','Flowers appeared on the redbud / before its leaves opened / in spring.','redbud 指春季先在裸枝上开出红粉色花簇的落叶树。','树木先开花后长叶。'),M('The botanist identified the redbud by its blue fruit and evergreen needles in the middle of winter.','The botanist identified the redbud by its reddish spring flowers on bare branches.','redbud 的典型特征是春天裸枝上的红粉色花朵，而非蓝果和常绿针叶。','meaning'),[q('When did the redbud flowers appear?','before the leaves opened','after evergreen needles fell','only beneath the ground','紫荆在叶片展开前先开花。'),q('What color were its flowers?','pink-red','bright blue','pure white','redbud 的花呈粉红至红色。',1,'context'),q('What kind of tree is a redbud?','a deciduous tree','an evergreen pine','a flowering vine with no branches','redbud 是落叶树。',1,'meaning'),q('Which words make up redbud?','red and bud','record and bud','recovery and branch','redbud 由 red 和 bud 组成。',1,'word-formation')]);
P('redden','Redden is formed from red and the verb-forming suffix -en; it means become red, especially in the face.',C('redden.s1','变红；脸红','Her cheeks reddened when the audience applauded the poem she had written in secret.','观众为她偷偷写的诗鼓掌时，她的脸颊红了起来。','Her cheeks reddened / when the audience applauded / her poem.','redden 指颜色变红，尤指人因情绪而脸红。','掌声让她羞红了脸。'),M('His cheeks reddened because they changed from red to completely colorless white.','His cheeks reddened as he blushed after the audience praised his poem.','redden 表示变红，变成白色与该动词含义相反。','meaning'),[q('What made her cheeks redden?','the audience applauded her poem','the audience ignored her completely','she mixed red paint with white','观众为她的诗鼓掌，她因此脸红。'),q('What does redden mean?','become red','become rectangular','become less recognizable','redden 指变红。',1,'meaning'),q('Which situation could make someone redden?','embarrassment during a public introduction','a quiet night alone with no emotion','a successful recovery from a fever only','在公开介绍时感到尴尬可能让人脸红。',1,'context'),q('Which suffix turns red into the verb redden?','-en','-ish','-ment','red 加 -en 构成动词 redden。',1,'word-formation')]);
P('reddish','Reddish is formed from red and -ish; it means partly red or having a color that is not a pure red.',C('reddish.s1','略带红色的','The stone looked reddish in the evening light, though its surface was mostly brown.','这块石头在傍晚的光线下略带红色，尽管表面大多呈棕色。','The stone looked reddish / in the evening light / though it was mostly brown.','reddish 表示颜色部分偏红，但并非纯红色。','棕色石头因光线显出红色调。'),M('The painter called the stone reddish even though it was bright green and contained no red tone.','The painter called the stone reddish because it had a faint red-brown tone.','reddish 表示带有红色调，纯绿色不符合该描述。','meaning'),[q('What color was the stone mostly?','brown','bright green','pure red','石头大多是棕色。',1,'context'),q('What does reddish mean?','partly red in color','exactly pure red','without any color','reddish 指略带红色。',1,'meaning'),q('Which object is reddish?','a brown tile with a faint red tint','a pure white sheet','a vivid blue sign','带淡红色调的棕色砖是 reddish。',1,'context'),q('What does -ish add to red?','somewhat or partly','the past tense','a person who uses red','-ish 表示“略微、带有某种特征”。',1,'word-formation')]);
P('redeem','Redeem came through Old French from Latin redimere, “buy back”; it means recover something by payment or exchange, make up for a fault, or save spiritually.',[C('redeem.s1','赎回；兑换','She redeemed the grocery coupons at the checkout and received a discount on the household supplies.','她在收银台兑换了食品优惠券，购买日用品时获得折扣。','She redeemed the coupons / at checkout / for a discount.','redeem.s1 指付钱赎回物品或兑换优惠券、代金券。','优惠券在收银台兑换成折扣。'),C('redeem.s2','挽回；弥补','The team redeemed its poor first half with two accurate goals after the break.','球队下半场攻入两粒精准进球，挽回了上半场的糟糕表现。','The team redeemed its poor first half / with two goals / after the break.','redeem.s2 指通过后续行动弥补错误或糟糕表现。','下半场的进球弥补了此前表现。'),C('redeem.s3','救赎；拯救','In the novel, the prisoner sought to redeem himself by protecting the people he had once betrayed.','小说中，囚犯试图保护曾被自己背叛的人，以此救赎自己。','The prisoner sought to redeem himself / by protecting / those he had betrayed.','redeem.s3 可指从罪恶、过错或道德困境中拯救、救赎。','保护他人是囚犯寻求救赎的行动。')],M('The shopper redeemed the coupon by tearing it up and throwing it away before asking for the discount.','The shopper redeemed the coupon by presenting it at checkout for the advertised discount.','兑换优惠券需要交给商家并换取折扣，丢弃优惠券不会产生兑换。','meaning'),[q('What did the shopper redeem at checkout?','grocery coupons','a lost bridge blueprint','a train recording','顾客在收银台兑换了食品优惠券。',1,'context'),q('How did the team redeem its poor first half?','scored two accurate goals after the break','lost by an even larger margin','recounted the first half without playing','球队通过下半场的两粒进球挽回了糟糕表现。',2,'context'),q('What did the prisoner do to redeem himself?','protected people he had betrayed','escaped and betrayed them again','exchanged a coupon for a discount','囚犯保护曾被自己背叛的人以寻求救赎。',3,'context'),q('Which meaning is used in “redeem a voucher”?','exchange it for a product or discount','make up for a poor performance','save someone from sin','redeem a voucher 指兑换代金券。',1,'meaning')]);
P('redefine','Redefine combines re- and define; it means state the meaning or limits of something again, often changing how it is understood.',C('redefine.s1','重新界定','The committee redefined “local resident” to include people who had lived in the district for at least six months.','委员会重新界定了“本地居民”，将已在该区居住至少六个月的人纳入其中。','The committee redefined “local resident” / to include people / living there six months.','redefine 指重新说明一个概念的含义或适用边界。','新的定义扩大了本地居民的范围。'),M('The committee redefined local resident by repeating the old definition word for word and making no change to its limits.','The committee redefined local resident by changing the eligibility period to six months.','重新界定意味着改变或重新说明边界，而非原样重复旧定义。','meaning'),[q('Who qualified under the committee’s new definition?','people living in the district for at least six months','only people who had moved away','everyone who visited once','新定义纳入了至少居住六个月的人。'),q('What does redefine mean?','state a meaning or boundary again, often changing it','recognize something from a familiar feature','recover money after a loss','redefine 指重新界定含义或范围。',1,'meaning'),q('Which action would redefine the age limit?','changing eligibility from 18 to 21','printing the same rule again unchanged','forgetting what the old rule said','把资格年龄从18岁改到21岁属于重新界定。',1,'context'),q('What does re- mean in redefine?','again','before','against','re- 在 redefine 中表示“重新、再次”。',1,'word-formation')]);
P('redemption','Redemption comes from Latin redemptio, related to redimere “buy back”; it means spiritual saving or the recovery of something lost.',C('redemption.s1','救赎；拯救；赎回','The novel presents the former thief’s redemption through years of service to the families he once harmed.','小说描写了这名前窃贼多年来服务曾受其伤害的家庭，从而获得救赎。','The novel presents his redemption / through years of service / to those he harmed.','redemption.s1 指救赎或重新获得失去之物。','他以持续行动弥补过去的伤害。'),M('The story called the former thief’s redemption complete because he continued harming the same families and refused to change.','The story portrayed his redemption through sustained efforts to repair the harm he had caused.','持续伤害他人且拒绝改变不能称为获得救赎。','meaning'),[q('How did the former thief seek redemption?','by serving families he had harmed','by harming those families again','by selling them a railway record','他通过服务曾受伤害的家庭寻求救赎。'),q('What can redemption mean?','spiritual saving or recovery of something lost','a recurring event only','a rectangular shape','redemption 可指救赎或赎回。',1,'meaning'),q('Which phrase uses redemption in the spiritual sense?','a story of moral redemption','the redemption of a coupon at checkout','a redemption of old glass into new bottles','moral redemption 指道德上的救赎。',1,'context'),q('Which verb is redemption historically linked to?','redeem','redefine','recount','redemption 与 redeem 同源。',1,'word-formation')]);
P('redemptioner','Redemptioner combines redemption and -er; historically it named a European immigrant who repaid the cost of Atlantic passage through years of bound labor after arrival.',C('redemptioner.s1','赎身移民','The archive listed a redemptioner who paid for passage to Pennsylvania by completing a term of labor after arrival.','档案记载了一名赎身移民，他抵达宾夕法尼亚后通过一段期限的劳役偿还了船票钱。','The archive listed a redemptioner / who repaid passage / through a term of labor.','redemptioner.s1 指以抵达后的契约劳役偿还跨洋旅费的历史移民。','移民通过约定年限的劳动偿还船费。'),M('The museum described the redemptioner as a passenger whose fare was paid in full before sailing and who owed no labor afterward.','The museum described the redemptioner as a migrant who repaid the passage cost through bound labor after arrival.','redemptioner 的历史含义包含以抵达后的契约劳役偿还船费。','meaning'),[q('How did the immigrant repay the Atlantic passage?','by completing a term of labor after arrival','by buying a rail ticket for the return trip','by writing a recommendation letter','这名移民通过抵达后的劳役偿还船费。'),q('Where did the archive say the redemptioner arrived?','Pennsylvania','the old station in the village','a rainforest in South America','档案记载他抵达宾夕法尼亚。',1,'context'),q('Who was historically called a redemptioner?','a migrant who worked to repay the cost of passage','a person who redeemed a coupon at a shop','a former prisoner who sought spiritual forgiveness','redemptioner 指通过契约劳役偿还船费的移民。',1,'meaning'),q('Which word is redemptioner built from?','redemption plus -er','red plus -ish','record plus -ing','redemptioner 由 redemption 加 -er 构成。',1,'word-formation')]);
P('redesign','Redesign combines re- and design; it means change the plan, appearance or structure of a product, place or system.',C('redesign.s1','改设计；重新设计','The city redesigned the bus map so riders could see transfer points without tracing every line by hand.','市政府重新设计了公交线路图，让乘客无需手动追踪每条线路就能看到换乘点。','The city redesigned the bus map / so riders could locate / transfer points easily.','redesign 指重新规划或改变事物的外观、结构。','新地图清楚标出了换乘点。'),M('The city said it redesigned the bus map but published the exact same map with no change to its layout or symbols.','The city redesigned the bus map by changing its layout and clearly marking transfer points.','如果布局和标识完全没变，就不能说重新设计了地图。','meaning'),[q('What did the city redesign?','the bus map','the passengers’ route memories','a redemption certificate','市政府重新设计了公交地图。'),q('What did the new map make easier to see?','transfer points','the color red in every street','the old railway’s history','新地图让乘客更容易看到换乘点。',1,'context'),q('What does redesign mean?','change a plan, appearance or structure','restore health after an illness','count votes again','redesign 指改变设计方案或结构。',1,'meaning'),q('What does re- signal in redesign?','doing the design again or differently','making the design red','designing only once','re- 表示重新或以不同方式设计。',1,'word-formation')]);
P('redevelopment','Redevelopment is formed from redevelop and -ment; it means rebuilding or refitting an older site, neighborhood or facility.',C('redevelopment.s1','旧区改造；再开发','The redevelopment of the riverside warehouses added apartments and public paths while retaining the historic brick walls.','河畔仓库改造后增建了公寓和公共步道，同时保留了历史砖墙。','The redevelopment added apartments and paths / while retaining / historic brick walls.','redevelopment 指拆改或翻新旧场地并重新建设。','旧仓库改造兼顾新用途和历史建筑。'),M('The city called the project redevelopment even though it left the abandoned site untouched and built nothing new.','The city called the project redevelopment because it refitted the old warehouses for housing and public use.','旧场地没有翻修或新建内容，就不属于 redevelopment。','meaning'),[q('What did the riverside redevelopment add?','apartments and public paths','a new clinic record system','a railway vote recount','河畔改造增建了公寓和公共步道。'),q('What did the project retain?','the historic brick walls','every unsafe warehouse unchanged','the site’s former vacancy','项目保留了历史砖墙。',1,'context'),q('What is redevelopment?','renewing an older place for new use','recording a place for later playback','making a red color darker','redevelopment 指改造旧场地并重新开发。',1,'meaning'),q('Which suffix forms redevelopment as a noun?','-ment','-able','-ish','redevelop 加 -ment 构成 redevelopment。',1,'word-formation')]);
P('redirect','Redirect combines re- and direct; it means send a person, message or object to a different place or direction.',C('redirect.s1','改道；重新指引','When the main bridge closed, traffic officers redirected cars to the eastern crossing.','主桥关闭后，交通警察把汽车引导至东侧桥梁。','Officers redirected the cars / to the eastern crossing / after the bridge closed.','redirect 指改变原来的去向或路线。','车辆在主桥关闭后改走东侧桥梁。'),M('Officers redirected traffic to the closed bridge and away from the only open crossing.','Officers redirected traffic to the eastern crossing while the main bridge was closed.','改道应引向可通行路线，而不是关闭的桥梁。','meaning'),[q('Why did officers redirect the cars?','the main bridge had closed','the eastern crossing was closed','the drivers wanted to return home','主桥关闭后，车辆被引导改道。'),q('Where did traffic go instead?','to the eastern crossing','back onto the closed bridge','into the river','车辆改走东侧桥梁。',1,'context'),q('What does redirect mean?','send something to a different route or place','send it back to its original route only','reconstruct it from evidence','redirect 指把人或物引向别的路线或地点。',1,'meaning'),q('Which prefix marks a changed direction in redirect?','re-','sub-','mis-','redirect 中 re- 与重新指引有关。',1,'word-formation')]);
P('rediscover','Rediscover combines re- and discover; it means encounter or find something again as if for the first time.',C('rediscover.s1','再度发现','During the renovation, the owners rediscovered a painted sign hidden behind a layer of plaster.','翻修期间，房主在一层灰泥后重新发现了一块彩绘招牌。','The owners rediscovered the sign / hidden behind plaster / during renovation.','rediscover 指再次找到或重新注意到先前已知、后来遗失或被忽略的事物。','招牌被遮住多年后再次被发现。'),M('The owners rediscovered the sign by throwing it away before anyone found it behind the plaster.','The owners rediscovered the sign when they uncovered it during renovation.','重新发现是找到被遮蔽的物品，不是先把它丢弃。','meaning'),[q('Where was the sign hidden?','behind a layer of plaster','inside the railway records','beneath the river crossing','招牌藏在一层灰泥后。'),q('When did the owners rediscover it?','during the renovation','before the building existed','after they deliberately destroyed it','房主在翻修时重新发现招牌。',1,'context'),q('What does rediscover mean?','find or encounter something again','design something for the first time','redirect traffic around a bridge','rediscover 指再次发现某物。',1,'meaning'),q('Which phrase uses rediscover naturally?','rediscover a forgotten song','rediscover a song by never finding it','rediscover the map before it was made','rediscover a forgotten song 表示重新发现一首旧歌。',1,'collocation')]);
P('redistribute','Redistribute combines re- and distribute; it means divide or assign something again, often changing how shares are allocated.',C('redistribute.s1','再分配','The council voted to redistribute emergency funds toward districts hit hardest by the flood.','委员会投票决定把应急资金重新分配给受洪灾影响最严重的地区。','The council voted to redistribute funds / toward districts / hit hardest by the flood.','redistribute 指再次分配资源，并可能改变各方所得份额。','资金被重新分配给受灾最重的地区。'),M('The council said it redistributed the emergency funds while leaving every dollar with the same district as before.','The council redistributed funds by shifting more support to the districts most affected by the flood.','重新分配意味着改变资源分配，而不是维持原状。','meaning'),[q('Where did the council direct more emergency funds?','districts hit hardest by the flood','districts untouched by the flooding only','the railway station’s record room','委员会把资金转向洪灾最严重的地区。'),q('What does redistribute mean?','divide or assign something again, changing shares','collect waste for processing','discover a hidden sign','redistribute 指重新分配资源。',1,'meaning'),q('Which action redistributes food?','moving extra supplies to a shelter with fewer meals','leaving all supplies in the same full warehouse','throwing away every unopened package','把多余食物转给缺少餐食的收容所属于再分配。',1,'context'),q('What does re- mean in redistribute?','again','under','against','re- 在 redistribute 中表示再次分配。',1,'word-formation')]);
P('redo','Redo combines re- and do; it means do an activity again, often to correct or improve the first result.',C('redo.s1','重做','The student had to redo the calculation after finding that she had entered the wrong interest rate.','发现输错利率后，学生不得不重新计算。','The student had to redo the calculation / after finding / the wrong rate.','redo 指再次完成某项工作，常为改正或改善第一次结果。','输入正确利率后需要重算。'),M('She redid the calculation by repeating the same incorrect rate and refusing to check the result.','She redid the calculation with the correct rate and checked the new result.','重做是重新完成任务以修正错误，照搬错误输入不会改正结果。','meaning'),[q('Why did the student redo the calculation?','she entered the wrong interest rate','the calculation had been approved as correct','the worksheet had no numbers','输错利率后学生需要重新计算。'),q('What should she do in the redo?','use the correct rate and check the result','repeat the wrong rate without checking','delete the calculation permanently','重算时要使用正确利率并检查结果。',1,'context'),q('What does redo mean?','do something again','recognize it for the first time','recover from an illness','redo 指把事情再做一次。',1,'meaning'),q('Which prefix means “again” in redo?','re-','pre-','un-','redo 中 re- 表示“再次”。',1,'word-formation')]);
P('redress','Redress comes from Old French redresser, “set straight again”; it can mean a remedy for a wrong or the act of correcting an injustice.',[C('redress.s1','补偿；补救办法','The tenants sought redress for the broken heating system and received a rent credit for the days without heat.','暖气系统损坏后，租户寻求补偿，并获得了无暖气期间的租金抵扣。','The tenants sought redress / and received a rent credit / for the days without heat.','redress.s1 指纠正坏状况或补偿受损一方的措施。','租户通过租金抵扣获得了补偿。'),C('redress.s2','纠正；申冤','The court ordered the agency to redress the unfair denial by reviewing the application under the correct rule.','法院命令该机构依据正确规则重新审查申请，以纠正不公正的拒绝。','The court ordered the agency to redress the denial / by reviewing / the application fairly.','redress.s2 作动词表示纠正错误或弥补不公。','机构被要求重新公平审理申请。')],M('The tenants received redress for the heating failure by paying an extra penalty to the landlord.','The tenants received redress for the heating failure through a rent credit from the landlord.','补偿应纠正受损方的不利处境，而不是让受损租户再交罚款。','meaning'),[q('What form of redress did the tenants receive?','a rent credit for the days without heat','a new heating bill added to their rent','a letter recommending the landlord','租户获得了无暖气期间的租金抵扣。',1,'context'),q('How did the agency redress the unfair denial?','reviewed the application under the correct rule','refused to look at the application again','charged the applicant a second fee','机构依据正确规则重新审查申请。',2,'context'),q('What does redress mean as a noun?','a remedy or compensation for a wrong','a repeated occurrence','a fast traditional dance','redress 作名词指补救或补偿。',1,'meaning'),q('Which verb phrase uses redress correctly?','redress an injustice','redress a person to stand upright in a chair','redress the vote into a recording','redress an injustice 表示纠正不公。',2,'collocation')]);
P('reduce','Reduce comes from Latin reducere, “lead back”; it can make an amount smaller, bring someone into a worse state, or simplify something.',[C('reduce.s1','减少；降低','The shop reduced the price of winter coats by twenty percent after the new season began.','新季节开始后，商店把冬季外套的价格降低了百分之二十。','The shop reduced the price / by twenty percent / after the new season began.','reduce.s1 指使数量、尺寸或价格变小。','商店下调了外套价格。'),C('reduce.s2','使沦为；使陷入','The prolonged drought reduced several farms to near bankruptcy when their crops failed.','长期干旱导致庄稼歉收，使几家农场濒临破产。','The drought reduced several farms / to near bankruptcy / after crops failed.','reduce.s2 常见于 reduce someone to，指使某人陷入更糟处境。','干旱使农场陷入严重财务困难。'),C('reduce.s3','归纳；简化','The editor reduced the long report to a one-page summary for the board.','编辑把长篇报告压缩成一页摘要供董事会阅读。','The editor reduced the long report / to a one-page summary / for the board.','reduce.s3 指把复杂内容变成较简单或较短的形式。','长报告被简化为一页摘要。')],M('The shop reduced coat prices by raising them from $80 to $120 after the sale began.','The shop reduced coat prices by lowering them from $120 to $80.','reduce 表示使价格变低，从80涨到120是提高价格。','meaning'),[q('By how much did the shop reduce coat prices?','twenty percent','two hundred percent','not at all','商店把外套价格降低了百分之二十。',1,'context'),q('What did the drought reduce the farms to?','near bankruptcy','a one-page report','a higher crop yield','干旱使农场濒临破产。',2,'context'),q('What did the editor reduce the long report to?','a one-page summary','a longer report with more detail','a set of farm accounts','编辑把长报告压缩成一页摘要。',3,'context'),q('Which meaning is used in “reduce the noise”?','make the amount or level smaller','bring someone into bankruptcy','simplify a report into a summary','reduce the noise 表示降低噪声大小。',1,'meaning')]);
P('reduction','Reduction is formed from reduce and -tion; it means the act or amount by which something is made smaller or lower.',C('reduction.s1','减少；降低','The reduction in energy use followed the factory’s switch to efficient motors and better insulation.','工厂改用高效电机并改善隔热后，能源消耗有所下降。','The reduction in energy use / followed the switch / to efficient motors.','reduction.s1 指数量、规模或程度变小的过程或幅度。','节能设备带来了能源消耗下降。'),M('The report called a rise in energy use a reduction even though the factory consumed more electricity each month.','The report called the lower monthly energy use a reduction.','消耗增加是上升，不是减少。','meaning'),[q('What followed the factory’s equipment upgrade?','a reduction in energy use','a reduction in insulation quality','a rise in monthly electricity use','工厂设备升级后能源使用减少。'),q('What does reduction mean?','the act or amount of making something smaller','a full recovery from illness','a second public election','reduction 指减少的行为或减少量。',1,'meaning'),q('Which phrase is natural?','a reduction in operating costs','a reduction of the costs upward','a reduction that increases the total','a reduction in costs 是自然搭配。',1,'collocation'),q('Which verb is reduction based on?','reduce','recruit','reel','reduction 由 reduce 加 -tion 构成。',1,'word-formation')]);
P('redundancy','Redundancy is related to Latin redundare, “overflow”; it can mean unnecessary excess or, especially in British English, loss of a job because work is no longer needed.',[C('redundancy.s1','多余；裁员','The company announced three redundancies after automating the filing system, leaving the affected employees time to seek other jobs.','文件系统自动化后，公司宣布裁撤三个岗位，让受影响员工有时间寻找新工作。','The company announced redundancies / after automating the filing system / and notified affected staff.','redundancy.s1 可指不再需要的状态，也可指岗位因不再需要而被裁撤。','自动化后公司裁撤了三个岗位。')],M('The company described the redundancies as new hires because it was adding three unnecessary positions to the payroll.','The company described the redundancies as job losses after those positions were no longer needed.','redundancy 在英式就业语境中指岗位不再需要导致的裁员，不是新增招聘。','meaning'),[q('What change led the company to announce redundancies?','automation of the filing system','a rise in demand for filing staff','a new recommendation letter','文件系统自动化后公司宣布裁撤岗位。'),q('What does redundancy mean in a workplace?','a job loss because the work is no longer needed','a promotion to a newly created post','a recurring reminder on a calendar','此处 redundancy 指岗位不再需要而失业。',1,'meaning'),q('Which situation is redundancy?','an employer removes a role after automating its tasks','a worker resigns to move to another city','a company hires more staff for new work','自动化后取消岗位属于 redundancy。',1,'context'),q('What older image is related to redundant and redundancy?','something overflowing or extra','something reassembled from pieces','a person leaning back','词源中的“溢出”引申为多余。',1,'word-formation')]);
P('redundant','Redundant comes from Latin redundare, “overflow”; it can mean unnecessary, laid off in British usage, or expressed with needless words.',[C('redundant.s1','多余的；不需要的','The backup alarm was redundant because the new sensor already warned staff whenever the tank began to overflow.','备用警报器是多余的，因为新传感器已能在水箱快要溢出时提醒员工。','The backup alarm was redundant / because the sensor / already gave the same warning.','redundant.s1 指已有其他事物完成相同功能，因此不再需要。','传感器已能预警，备用警报器功能重复。'),C('redundant.s2','被裁员的（英式）','Several redundant workers received career advice after the factory moved its production overseas.','工厂把生产转移到海外后，几名被裁员工获得了职业咨询。','Several redundant workers received advice / after the factory / moved production overseas.','redundant.s2 在英式英语中可指因岗位不再需要而被裁员。','生产外迁导致工人失去岗位。'),C('redundant.s3','冗赘的（语言）','The editor deleted the redundant phrase “return back” because return already means go back.','编辑删掉了冗赘的 return back，因为 return 本身已经表示返回。','The editor deleted “return back” / because return / already means go back.','redundant.s3 指表达中重复、不必要的词语。','删去 back 后意思不变。')],M('The sentence “return back home” is not redundant because return never means to go back.','The sentence “return back home” is redundant because return already means go back.','return 与 back 重复表达“返回”，因此 back 多余。','meaning'),[q('Why was the backup alarm redundant?','the new sensor already gave the same warning','the tank had no sensor at all','the alarm measured the workers’ pay','新传感器已发出同样预警，因此备用警报多余。',1,'context'),q('Why were the factory workers called redundant?','their jobs were no longer needed after production moved','they had received promotions','they had repeated a phrase in writing','工厂外迁后岗位不再需要，员工因此被裁。',2,'context'),q('Which phrase did the editor remove as redundant?','return back','return home','go back home','return back 重复表达“返回”。',3,'context'),q('Which use of redundant is British employment usage?','a redundant worker whose position was removed','a redundant alarm that duplicates another warning','a redundant phrase that repeats a meaning','redundant worker 指因岗位取消而被裁的员工。',1,'meaning')]);
P('redundantly','Redundantly is formed from redundant and -ly; it means with unnecessary repetition or with extra parts kept as backup.',[C('redundantly.s1','多余地；冗余地','The manual redundantly repeated the same warning in three adjacent paragraphs, so the editor combined them.','手册在相邻三段中重复了同一条警告，编辑因此把它们合并。','The manual redundantly repeated the warning / in three adjacent paragraphs.','redundantly.s1 指不必要地重复信息，也可指额外保留冗余备份。','相邻段落多次重复同一警告。')],M('The manual stated the warning redundantly only once and never repeated it or added any extra backup.','The manual stated the warning redundantly in three adjacent paragraphs.','只陈述一次没有重复，不属于 redundantly。','meaning'),[q('How many adjacent paragraphs repeated the warning?','three','one','none','手册在相邻三段重复了警告。'),q('What did the editor do with the redundant passages?','combined them','copied them into three more paragraphs','removed the warning from every copy','编辑把重复段落合并了。',1,'context'),q('What does redundantly mean?','with unnecessary repetition or extra backup','in a way that corrects an error','in a way that restores health','redundantly 指多余地重复或保留冗余备份。',1,'meaning'),q('Which sentence uses redundantly?','The report redundantly stated the same deadline twice.','The report stated the deadline once, clearly.','The report redirected the train to another station.','第一句重复陈述截止日期，属于 redundantly。',1,'grammar')]);
P('redwing','Redwing combines red and wing; it names the redwing thrush, Turdus iliacus, identified by reddish coloring beneath its wings.',C('redwing.s1','红翼鸫','A redwing searched the berry hedge at dawn, showing the reddish patch beneath its wing as it turned.','黎明时，一只红翼鸫在浆果树篱中觅食，转身时露出翅膀下方的红褐色斑纹。','A redwing searched the hedge / and showed its reddish patch / beneath the wing.','redwing 指翅膀下方带红褐色斑纹的一种鸫。','鸟转身时露出了翼下红斑。'),M('The field guide identified the redwing by a bright blue patch beneath its wing and no reddish markings.','The field guide identified the redwing by the reddish patch beneath its wing.','redwing 的名称来自翼下红色斑纹，不是蓝斑。','meaning'),[q('When did the redwing search the berry hedge?','at dawn','at midnight inside a railway station','during a theater rehearsal','红翼鸫黎明时在树篱中觅食。'),q('Which marking helped identify the bird?','a reddish patch beneath its wing','a blue band around its tail','a red coat across its back','翼下的红褐色斑纹有助于辨认红翼鸫。',1,'context'),q('What species is called a redwing in this entry?','a thrush, Turdus iliacus','a migratory redbud tree','a kind of railway signal','此处 redwing 指 Turdus iliacus 鸫类。',1,'meaning'),q('Which parts form the name redwing?','red and wing','reed and wing','red and warning','redwing 由 red 与 wing 组合而成。',1,'word-formation')]);
P('redwood','Redwood combines red and wood; it names a giant sequoia-related tree, especially the coast redwood, or the wood obtained from it.',C('redwood.s1','红杉；红杉木','The hikers walked among coast redwoods whose trunks rose above the fog along the northern California trail.','徒步者穿行在加州北部步道的海岸红杉林中，树干高耸于雾气之上。','The hikers walked among redwoods / whose trunks rose / above the fog.','redwood.s1 指巨大的红杉树，也可指其木材。','徒步者在高大的海岸红杉间行走。'),M('The guide called the tiny annual herb a redwood even though it had no woody trunk and never grew tall.','The guide called the towering coast tree a redwood because it belonged to the giant sequoia group.','redwood 指大型木本树，不是矮小的一年生草本。','meaning'),[q('Where did the hikers walk?','among coast redwoods in northern California','through a small redbud orchard','along a coral reef','徒步者在加州北部的海岸红杉林中行走。'),q('What did the redwood trunks rise above?','the fog','the railway platform','the berry hedge','红杉树干高耸于雾气之上。',1,'context'),q('What can redwood mean?','a large sequoia-related tree or its wood','a red-winged bird only','a red-colored annual flower','redwood 可指红杉树或红杉木材。',1,'meaning'),q('How is the name redwood formed?','red plus wood','re- plus wood','reed plus red','redwood 由 red 和 wood 组合而成。',1,'word-formation')]);
P('reed','Reed comes from Old English hrēod; it names a tall wetland plant with a hollow stem or the thin vibrating strip in some wind instruments.',[C('reed.s1','芦苇','Tall reeds lined the marsh, and their hollow stems bent when a gust swept across the water.','沼泽边长满高高的芦苇，阵风掠过水面时中空的茎秆随之弯曲。','Tall reeds lined the marsh / and their hollow stems bent / in the wind.','reed.s1 指生长在湿地、茎秆中空的高大植物。','芦苇生长在沼泽并随风弯曲。'),C('reed.s1','簧片','The clarinetist replaced a cracked reed before rehearsal because the old one made the notes squeak.','排练前，单簧管演奏者换掉了破裂的簧片，因为旧簧片会让音符发出刺耳声。','The clarinetist replaced the reed / before rehearsal / because it made notes squeak.','reed.s1 也指单簧管、双簧管或风琴中振动发声的簧片。','演奏者更换了损坏的簧片。')],M('The clarinetist replaced the reed by planting the instrument’s thin vibrating strip in the marsh.','The clarinetist replaced the cracked reed, the thin strip that vibrates to produce sound.','乐器中的 reed 是发声簧片，不是要种在沼泽里的植物。','meaning'),[q('Where did the tall reeds grow?','along the marsh','inside the clarinet','on a redwood trunk','芦苇生长在沼泽边。',1,'context'),q('Why did the clarinetist replace the reed?','the cracked one made the notes squeak','the reed had grown too tall in the marsh','the instrument had no hollow stem','旧簧片破裂并导致声音刺耳。',1,'context'),q('What is a reed in a wind instrument?','a thin vibrating strip that helps produce sound','a tall plant with a hollow stem only','a metal track for a train','乐器中的 reed 是振动发声的簧片。',1,'meaning'),q('Which origin is given for the plant word reed?','Old English hrēod','Latin redimere','Old French redresser','reed 源自古英语 hrēod。',1,'word-formation')]);
P('reef','Reef is recorded in English for a ridge or shoal near the sea surface; its deeper origin is uncertain, so the word’s history is stated cautiously.',C('reef.s1','礁；礁石','The survey boat slowed near the reef because shallow rocks lay just below the surface.','调查船在礁石附近减速，因为水面下方有浅礁。','The boat slowed near the reef / because rocks lay / just below the surface.','reef.s1 指靠近海面的一列岩石、珊瑚或沙脊。','浅礁隐藏在水面下，对船只构成危险。'),M('The captain steered directly over the reef because its rocks stood high and clearly above the water.','The captain slowed near the reef because shallow rocks were hidden just below the surface.','礁石可能潜伏在海面下，直接驶过会有搁浅或碰撞风险。','meaning'),[q('Why did the survey boat slow down?','shallow rocks lay just below the surface','the reef was a safe deep-water harbor','the boat was entering a redwood forest','水面下有浅礁，因此调查船减速。'),q('What is a reef?','a ridge of rocks or sand near the sea surface','a tall wetland plant','a cylinder holding film','reef 指海面附近的岩石或沙脊。',1,'meaning'),q('Where might a reef create a navigation hazard?','in shallow coastal water','on a dry railway platform','inside a theater dining hall','浅海中的礁石可能危及航行。',1,'context'),q('What is said about reef’s deeper etymology?','it is uncertain','it certainly comes from red and wood','it comes directly from Latin for remember','reef 的更深词源尚不确定。',1,'word-formation')]);
P('reek','Reek comes from Old English rēocan, “to smoke or emit vapor”; as a verb it means give off a very bad smell.',C('reek.s1','发出恶臭','The abandoned refrigerator began to reek after the power failed and the food spoiled inside.','断电后食物在废弃冰箱里变质，冰箱开始散发恶臭。','The refrigerator began to reek / after the power failed / and food spoiled.','reek 指散发令人非常不快的气味。','食物变质使冰箱发臭。'),M('The refrigerator reeked pleasantly of fresh lemons after spoiled food had been left inside for a week.','The refrigerator reeked of spoiled food after the power failed.','变质食物通常产生恶臭，不会散发清新的柠檬香气。','meaning'),[q('What caused the refrigerator to reek?','food spoiled after the power failed','fresh lemons had just been added','the appliance had been cleaned thoroughly','冰箱断电后食物变质导致恶臭。'),q('What does reek mean?','give off a very bad smell','make a soft musical sound','become red with embarrassment','reek 指发出难闻的气味。',1,'meaning'),q('Which sentence uses reek naturally?','The drain reeked of rotten eggs.','The clean towel reeked pleasantly of fresh soap.','The clerk reeked the report into a summary.','排水口散发臭鸡蛋味，符合 reek 的含义。',1,'context'),q('Which older sense is linked to the Old English source of reek?','emit smoke or vapor','return money by payment','count a vote again','reek 的古英语词源与冒烟、散发蒸气有关。',1,'word-formation')]);
P('reel','Reel is an old Germanic word for a winding cylinder; separate uses name a traditional dance, unsteady movement, or the act of winding onto a spool.',[C('reel.s1','卷轴；线轴；胶片盘','The technician loaded a reel of cable onto the winch before lowering the camera into the well.','技师把一卷电缆装到绞车上，再把摄像机放入井中。','The technician loaded a cable reel / onto the winch / before lowering the camera.','reel.s1 指绕线、金属丝或胶片的圆筒形卷轴。','绞车上的线轴承载着电缆。'),C('reel.s2','里尔舞；舞曲段','The fiddler played a lively reel while the dancers moved quickly around the village hall.','提琴手演奏欢快的里尔舞曲时，舞者在村礼堂里快速起舞。','The fiddler played a reel / while dancers moved / around the hall.','reel.s2 指快速的传统舞蹈或其中一段舞曲。','舞者随着里尔舞曲快速起舞。'),C('reel.s3','蹒跚；眩晕','After standing up too quickly, he reeled toward the wall and waited for the dizziness to pass.','他起身太快后踉跄着走向墙边，等眩晕感消退。','He reeled toward the wall / after standing too quickly / and waited for the dizziness to pass.','reel.s3 作动词表示步履不稳或感到天旋地转。','起身过快使他眩晕踉跄。'),C('reel.s4','卷；绕','She reeled the fishing line onto its spool after checking that the hook was clear.','确认鱼钩已收好后，她把钓线绕回线轴。','She reeled the fishing line / onto its spool / after clearing the hook.','reel.s4 作动词表示把线或胶片缠绕在线轴上或从上面放出。','钓线被重新绕在线轴上。')],M('The technician loaded a reel of cable by removing the spool and scattering the loose cable across the floor.','The technician loaded the cable reel onto the winch so the line could be wound and lowered safely.','reel 是收纳和缠绕电缆的卷轴，不是把线散在地上。','meaning'),[q('What did the technician load onto the winch?','a reel of cable','a village dance floor','a bowl of spoiled food','技师把电缆卷轴装到绞车上。',1,'context'),q('What did the fiddler play for the dancers?','a lively reel','a recorded station announcement','a warning about the reef','提琴手演奏了欢快的里尔舞曲。',2,'context'),q('Why did the man reel toward the wall?','he felt dizzy after standing too quickly','he was winding fishing line onto a spool','he was dancing a traditional reel','他起身太快后眩晕踉跄。',3,'context'),q('What did she do with the fishing line?','reeled it onto its spool','recounted it at the harbor','recruited it for a dance','她把钓线绕回线轴。',4,'context')]);
P('reelect','Reelect combines re- and elect; it means choose an office-holder for another term by voting again.',C('reelect.s1','重选；使连任','Residents voted to reelect the mayor after she completed the flood-defense project ahead of schedule.','市长提前完成防洪工程后，居民投票让她连任。','Residents voted to reelect the mayor / after she completed / the flood-defense project.','reelect 指再次通过投票选出在任者。','居民投票决定让市长继续任职。'),M('The voters reelected the mayor by removing her from office and choosing a different candidate.','The voters reelected the mayor by choosing her for another term.','再次选出同一位在任者才是 reelection，不是改选其他人。','meaning'),[q('What project did the mayor complete before voters reelected her?','the flood-defense project','a cable-reel replacement','a railway dining hall','市长提前完成了防洪工程。'),q('How did residents choose to reelect the mayor?','they voted to give her another term','they appointed a different candidate instead','they canceled the election permanently','居民投票让市长连任。',1,'context'),q('What does reelect mean?','choose an office-holder again by vote','examine a decision again','enter a building again','reelect 指通过再次投票选出同一任职者。',1,'meaning'),q('What does re- mean in reelect?','again','before','without','re- 表示再次选举。',1,'word-formation')]);
P('reelection','Reelection combines re- and election; it is a further term won by an office-holder through another vote.',C('reelection.s1','再次当选；连任','The senator began campaigning for reelection after the election office confirmed the date of the next vote.','选举办公室确认下次投票日期后，参议员开始竞选连任。','The senator began campaigning for reelection / after officials confirmed / the next vote date.','reelection 指在新一轮投票中再次当选并获得下一任期。','参议员开始为下一任期竞选。'),M('The senator celebrated reelection before any vote occurred and after losing the only election held.','The senator celebrated reelection after voters chose her for another term.','reelection 只有在新一轮投票再次当选后才成立。','meaning'),[q('When did the senator begin campaigning for reelection?','after the next vote date was confirmed','before the previous term began','after she retired permanently','参议员在确认下次投票日期后开始竞选连任。'),q('What does reelection mean?','winning another term through a new vote','being appointed without another vote','a review of a past election only','reelection 指通过新一轮投票再次当选。',1,'meaning'),q('Which phrase is natural?','campaign for reelection','campaign a reelection to the office','reelection the senator after retirement','campaign for reelection 是自然搭配。',1,'collocation'),q('Which verb is reelection based on?','reelect','recount','redress','reelection 由 reelect 加 -ion 构成。',1,'word-formation')]);
P('reenter','Reenter combines re- and enter; it means go into a place again or return to an activity after leaving it.',C('reenter.s1','重新进入；重返','After the alarm was cleared, the staff reentered the laboratory wearing fresh protective gear.','警报解除后，工作人员穿上新的防护装备重新进入实验室。','The staff reentered the laboratory / after the alarm was cleared / in fresh protective gear.','reenter 指再次进入某处，也可指重新参与某项活动。','警报解除后员工返回实验室。'),M('The staff reentered the laboratory by remaining outside the locked building and never going through its entrance.','The staff reentered the laboratory after the alarm cleared and the doors reopened.','重新进入要求先进入场所；一直留在门外并未 reenter。','meaning'),[q('When did the staff reenter the laboratory?','after the alarm was cleared','while the alarm was still active','before the laboratory was built','警报解除后员工重新进入实验室。'),q('What did they wear when reentering?','fresh protective gear','their old contaminated coats','a coat made from redwood','员工穿着新的防护装备返回实验室。',1,'context'),q('What does reenter mean?','go into a place again or return to an activity','leave a place for the first time','redirect someone to a new location','reenter 指重新进入或重返某项活动。',1,'meaning'),q('Which context uses reenter figuratively?','reenter the workforce after caring for family','reenter the laboratory through its door','reenter a room after an alarm clears','重返职场属于 reenter 的比喻性活动用法。',1,'context')]);
P('reevaluate','Reevaluate combines re- and evaluate; it means judge or assess something again in light of new facts or changed conditions.',C('reevaluate.s1','重新评价；再评估','The committee agreed to reevaluate the bridge plan after engineers found cracks in the supporting beams.','工程师发现支撑梁裂缝后，委员会同意重新评估桥梁方案。','The committee agreed to reevaluate the plan / after engineers found / cracks in the beams.','reevaluate 指依据新信息再次评估判断。','新发现的裂缝促使委员会重审方案。'),M('The committee reevaluated the bridge plan by refusing to examine the newly discovered cracks.','The committee reevaluated the bridge plan after examining the cracks reported by engineers.','重新评估应考虑新证据，而不是拒绝查看新发现。','meaning'),[q('What new evidence prompted reevaluation?','cracks in the supporting beams','a redbud blooming near the bridge','an old recording of a town meeting','支撑梁裂缝促使委员会重新评估方案。',1,'context'),q('What does reevaluate mean?','judge something again using new facts','elect the same official again','reconstruct a bridge from photographs','reevaluate 指根据新事实再次评估。',1,'meaning'),q('Which situation calls for reevaluation?','new test results contradict the original assessment','the decision remains unchanged and no new facts appear','a calendar reminder arrives as usual','新检测结果与原评估矛盾时应重新评估。',1,'context'),q('What does re- mean in reevaluate?','again','against','before','re- 表示再次评估。',1,'word-formation')]);
P('reexamine','Reexamine combines re- and examine; it means inspect, question or study something another time.',C('reexamine.s1','重新审查；复查','The auditor reexamined the invoices after noticing that two payment dates appeared twice.','发现两个付款日期重复后，审计员重新检查了发票。','The auditor reexamined the invoices / after noticing / repeated payment dates.','reexamine 指再次仔细检查或研究。','日期重复促使审计员复核发票。'),M('The auditor reexamined the invoices by refusing to look at them after spotting duplicated dates.','The auditor reexamined the invoices carefully after spotting duplicated dates.','reexamine 意味着再次检查，发现问题后拒绝查看并不是复查。','meaning'),[q('What did the auditor notice?','two payment dates appeared twice','the invoices had no dates at all','the auditor had already filed a reelection form','审计员发现两个付款日期重复。'),q('What did the auditor reexamine?','the invoices','the bridge beams','the election ballots','审计员重新检查了发票。',1,'context'),q('What does reexamine mean?','inspect or study something again','repair something by rebuilding it','send something to another address','reexamine 指再次检查或研究。',1,'meaning'),q('Which action is a reexamination?','checking a medical scan again after a new symptom appears','reading a report once and filing it without review','recruiting a new auditor','出现新症状后再次查看影像属于复查。',1,'context')]);
P('refectory','Refectory comes from Medieval Latin refectorium, a place for refreshment; it names a large dining room in a college or religious community.',C('refectory.s1','餐厅；食堂','Students gathered in the college refectory for dinner before returning to the library to study.','学生们先在学院食堂聚餐，然后回图书馆学习。','Students gathered in the refectory / for dinner / before returning to study.','refectory 指学院或宗教团体成员集体用餐的大房间。','学生在学院食堂用晚餐。'),M('The college called the refectory a private bedroom where students slept alone and never ate together.','The college called the refectory its large dining room where students ate together.','refectory 是集体用餐的餐厅，不是卧室。','meaning'),[q('Where did students eat dinner?','in the college refectory','in the library stacks','beside the railway railhead','学生在学院食堂吃晚餐。'),q('What did students do after dinner?','returned to the library to study','reentered the refectory to sleep alone','recruited new staff','学生晚餐后回图书馆学习。',1,'context'),q('What is a refectory?','a large shared dining room','a room for sleeping alone','a tool for raking leaves','refectory 是供集体用餐的大餐厅。',1,'meaning'),q('What idea is behind the Latin source of refectory?','refreshment','reelection','reconstruction','refectory 的拉丁词源与“恢复体力、进餐”有关。',1,'word-formation')]);
P('refer','Refer comes from Latin referre, “bring back”; it can mention something, consult a source, send a case to someone else, or indicate what something denotes.',[C('refer.s1','提到；谈及','The speaker referred to the flood in her opening remarks but spent most of the talk on the new bridge design.','发言者在开场时提到了洪水，但演讲的大部分内容都讲新桥设计。','The speaker referred to the flood / in her opening remarks / before discussing the bridge.','refer.s1 指在说话或写作中提及某人或某事。','演讲者简短提到洪水。'),C('refer.s2','查阅；参考','For the exact dosage, refer to the medicine label rather than relying on an old note.','要确认准确剂量，请查阅药品标签，不要只依赖旧笔记。','Refer to the medicine label / for the exact dosage / rather than an old note.','refer.s2 指查阅书籍、文件或说明以获取信息。','药品标签是剂量信息的参考来源。'),C('refer.s3','转诊；提交；委托','The clinic referred the patient to a specialist after the first examination raised concerns.','初步检查发现疑虑后，诊所把患者转诊给专科医生。','The clinic referred the patient / to a specialist / after the first examination.','refer.s3 指把患者、问题或案件交给有相应职责的人处理。','诊所把患者转给专科医生。'),C('refer.s4','指的是；涉及','In the contract, the phrase “covered period” refers to the months listed in Schedule B.','合同中的“保障期间”指附表B中列出的那些月份。','“Covered period” refers to the months / listed in Schedule B / in the contract.','refer.s4 指某词语、符号或表达所代表的对象。','合同定义了该术语所指的月份。')],M('The clinic referred the patient to a specialist by refusing to send the case to anyone and keeping the patient without further care.','The clinic referred the patient to a specialist for further examination.','转诊是把患者交给专科人员继续处理，不是拒绝转交。','meaning'),[q('What did the speaker refer to briefly?','the flood','the medicine label dosage','a specialist referral','发言者开场时提到了洪水。',1,'context'),q('Where should a reader refer for the exact dosage?','the medicine label','an unrelated old recording','the bridge design contract only','准确剂量应查阅药品标签。',2,'context'),q('Who received the patient after the first exam?','a specialist','the public speaker','the contract’s Schedule B','患者被转诊给专科医生。',3,'context'),q('What does “covered period” refer to in the contract?','the months listed in Schedule B','the speaker’s opening remarks','the patient’s first examination','合同中 covered period 指附表B列出的月份。',4,'meaning')]);
P('refer to','Refer to combines refer with the preposition to; it means mention a subject or consult a source for information.',C('refer to.s1','提到；查阅','The lab manual says to refer to the safety chart before mixing the cleaning agents.','实验室手册要求在混合清洁剂前查阅安全图表。','The manual says to refer to the chart / before mixing / the cleaning agents.','refer to 可表示提及某事，也可表示查阅资料；此例中指查阅图表。','操作者先查看安全图表再混合清洁剂。'),M('The lab manual told workers to refer the chart before mixing agents, using the phrase without the required preposition to.','The lab manual told workers to refer to the safety chart before mixing agents.','表示查阅资料时，refer 后需要介词 to。','grammar'),[q('What should workers consult before mixing the agents?','the safety chart','the redwing field guide','the election record','工作人员应先查阅安全图表。'),q('What does refer to mean in the lab instruction?','consult the chart for information','send the chart to a specialist','rebuild the chart from old pieces','此处 refer to 表示查阅图表。',1,'meaning'),q('Which sentence uses refer to to mean “mention”?','The report refers to three earlier inspections.','Please refer to page six for dosage details.','The clinic referred the patient to a specialist.','第一句 refer to 表示提及三次检查。',1,'meaning'),q('Which form is standard when consulting a source?','refer to the manual','refer the manual','refer at the manual','查阅资料应说 refer to the manual。',1,'grammar')]);
})();
